INSERT INTO lessons (id, title, subtitle, level, day, category, data) VALUES
('second-conditional-b1', 'Second Conditional', 'If + Past Simple, would + V¹ — xayoliy va gipotetik vaziyatlar', 'B1', 1, 'Conditionals', '{"formulas":[{"color":"green","label":"Second Conditional — Standard","structure":"If + Subject + V₂ , Subject + would + V¹\n  If I had more money, I would buy a car.","explanation":"Second Conditional xayoliy vaziyatlar uchun. ''If'' qismida Past Simple, natija qismida ''would + V¹'' ishlatiladi.","whenToUse":"Hozir yoki kelajakdagi real bo''lmagan, xayoliy vaziyatlar haqida gapirganda.","example":"If I lived near the sea, I would swim every day. (Agar dengiz yaqinida yashasam, har kuni suzardim)"},{"color":"blue","label":"If I were you... — Maslahat","structure":"If I were you, I would + V¹\n  If I were you, I would see a doctor.","explanation":"''If I were you'' — eng keng tarqalgan Second Conditional iborasi. Maslahat berish uchun ishlatiladi. ''I was'' EMAS, ''I were''!","whenToUse":"Kimgadir maslahat berishda: ''If I were you, I would...'' (Agar men sizning o''rningizda bo''lsam...)","example":"If I were you, I would take that job. (Men sizning o''rningizda bo''lsam, o''sha ishni qabul qilardim)"},{"color":"orange","label":"Inverted Second Conditional","structure":"Were + Subject + ... , Subject + would + V¹\n  Were I rich, I would travel the world.","explanation":"Rasmiy uslubda ''if'' tushib qoladi va were subjectdan oldin keladi. Bu inversion deyiladi.","whenToUse":"Rasmiy yozuvda, akademik matnlarda, ''if'' so''zini ishlatmasdan xayoliy shartni ifodalashda.","example":"Were it possible, we would help everyone. (Agar imkoni bo''lsa, hammaga yordam berardik)"},{"color":"purple","label":"Second Conditional with ''could''","structure":"If + Subject + V₂ , Subject + could + V¹\n  If I had wings, I could fly.","explanation":"''Would'' o''rniga ''could'' (would be able to) ishlatilsa, qobiliyat yoki imkoniyat ma''nosini beradi.","whenToUse":"Xayoliy vaziyatda qobiliyat yoki imkoniyat haqida gapirganda.","example":"If I spoke English fluently, I could work abroad. (Agar ingliz tilida ravon gapirsam, chet elda ishlay olardim)"}],"rules":["1️⃣ SECOND CONDITIONAL NIMA?\n\nSecond Conditional — hozir yoki kelajakdagi REAL BO''LMAGAN vaziyatlar uchun.\n\n📌 TUZILISHI:\n  If + Past Simple, would + V¹\n  → If I had a car, I would drive to work. (Mashinam bo''lsa, ishga haydab borardim)\n  → Haqiqat: Mening mashinam yo''q.\n  → Second Conditional bilan xayoliy vaziyatni ifodalaymiz.\n\n🔴 Bu REAL vaziyatlar uchun EMAS. Agar haqiqiy bo''lishi mumkin bo''lsa, First Conditional ishlating.","2️⃣ IF BO''LIMI — PAST SIMPLE\n\n''If'' qismida Past Simple ishlatiladi:\n  If I HAD more money...\n  If she LIVED near here...\n  If they DIDN''T work so hard...\n\n📌 SUBJUNCTIVE MOOD: ''If I was'' emas, ''If I WERE''\n  If I were you... (not: If I was you)\n  If she were here... (not: If she was here)\n\n🔴 ''Were'' barcha shaxslar uchun bir xil: I were, he were, they were","3️⃣ NATIJA BO''LIMI — WOULD + V¹\n\nNatija qismida ''would + V¹'' ishlatiladi:\n  ...I would travel the world.\n  ...she would be happier.\n  ...they would buy a house.\n\n🔴 Shart qismida ''would'' ISHLATILMAYDI!\n  ❌ If I WOULD HAVE more money...\n  ✅ If I HAD more money...\n\n📌 ''Would'' faqat natija bo''limida ishlatiladi, ''if'' bo''limida EMAS.","4️⃣ MASLAHAT: IF I WERE YOU...\n\nEng keng tarqalgan Second Conditional iborasi:\n  If I were you, I would see a doctor.\n  If I were you, I would study more.\n  If I were you, I wouldn''t go there.\n\nBu ibora o''zbekchada ''Men sizning o''rningizda bo''lsam...'' degan ma''noni bildiradi.\n\n📌 IELTS TIP: ''If I were you'' — Speaking da maslahat berishda juda tabiiy va keng tarqalgan ibora.","5️⃣ SECOND VS FIRST CONDITIONAL\n\n📌 First Conditional (real): If it rains, I will take an umbrella.\n  → Haqiqatan ham yomg''ir yog''ishi mumkin (50% ehtimol).\n\n📌 Second Conditional (unreal): If it rained, I would take an umbrella.\n  → Yomg''ir yog''ishi kutilmayapti, lekin agar yog''sa... (0-10% ehtimol).\n\n🔴 Asosiy farq: First = real (will), Second = unreal (would).\n🔴 Zamonda farq: First = If + Present, will + V¹ / Second = If + Past, would + V¹","6️⃣ COULD VA MIGHT BILAN\n\n''Would'' o''rniga ''could'' (qobiliyat) yoki ''might'' (ehtimol) ishlatish mumkin:\n  If I had more time, I could learn piano. (o''rgana olardim)\n  If she asked me, I might help. (yordam berishim mumkin edi)\n\n📌 FARQLAR:\n  • Would = aniq natija: I would go. (albatta borardim)\n  • Could = qobiliyat: I could go. (bora olardim)\n  • Might = ehtimol: I might go. (balki borardim)\n\n📌 ''Might'' would dan kamroq ishonch bildiradi.","7️⃣ O''ZBEKCHA XATOLAR\n\n📌 ''If'' qismida ''would'' ishlatish:\n  ❌ If I would have money...\n  ✅ If I had money...\n\n📌 ''Was'' o''rniga ''were'' ishlatmaslik:\n  ❌ If I was you...\n  ✅ If I were you...\n\n📌 ''Will'' ni natija qismida ishlatish:\n  ❌ I will buy a house.\n  ✅ I would buy a house.\n\n📌 First va Second ni aralashtirish:\n  ❌ If it rains, I would stay.\n  ✅ If it rained, I would stay. (Second = unreal)\n  ✅ If it rains, I will stay. (First = real)"],"vocabulary":[{"en":"hypothetical","uz":"xayoliy, faraziy","example":"A hypothetical situation is not real.","rule":"Second Conditional = hypothetical"},{"en":"unreal","uz":"real bo''lmagan","example":"Second Conditional describes unreal situations.","rule":"not real / imaginary"},{"en":"wishful thinking","uz":"xayol, orzu","example":"If I were rich is wishful thinking.","rule":"imagining a different reality"},{"en":"subjunctive","uz":"subjunktiv mayl","example":"If I were (not was) = subjunctive.","rule":"were for all persons"},{"en":"condition","uz":"shart","example":"The ''if'' part is the condition.","rule":"if + Past Simple"},{"en":"result","uz":"natija","example":"The ''would'' part is the result.","rule":"would + V¹"},{"en":"impossible","uz":"imkonsiz","example":"If I were a bird would be impossible.","rule":"can''t happen"},{"en":"advice","uz":"maslahat","example":"If I were you = common advice phrase.","rule":"giving suggestions"},{"en":"imaginary","uz":"xayoliy","example":"We use Second Conditional for imaginary scenarios.","rule":"not real"},{"en":"inversion","uz":"teskari so''z tartibi","example":"Were I rich = inverted If I were rich.","rule":"formal: drop ''if'', invert"},{"en":"were to","uz":"agar ...sa edi","example":"If I were to lose my job...","rule":"more formal if clause"},{"en":"otherwise","uz":"aks holda","example":"I would help; otherwise I wouldn''t offer.","rule":"contrasting real vs unreal"},{"en":"luck","uz":"omad","example":"If I had luck, I would win.","rule":"unreal condition"},{"en":"opportunity","uz":"imkoniyat","example":"If I had the opportunity, I would travel.","rule":"unreal opportunity"},{"en":"alternative","uz":"muqobil","example":"Would could be replaced by might or could.","rule":"could/might + V¹"}],"examples":[{"en":"If I had more money, I would buy a house.","uz":"Agar ko''proq pulim bo''lsa, uy sotib olardim."},{"en":"If she lived in Tashkent, we would meet every day.","uz":"Agar u Toshkentda yashasa, har kuni uchrashardik."},{"en":"If I were you, I would study more.","uz":"Men sizning o''rningizda bo''lsam, ko''proq o''qirdim."},{"en":"If we didn''t have exams, we would travel.","uz":"Agar imtihonlarimiz bo''lmasa, sayohat qilardik."},{"en":"If I knew the answer, I would tell you.","uz":"Agar javobni bilsam, sizga aytardim."},{"en":"Were I rich, I would help the poor.","uz":"Agar boy bo''lsam, kambag''allarga yordam berardim."},{"en":"If she spoke English, she could work abroad.","uz":"Agar u ingliz tilida gapirsa, chet elda ishlay olardi."},{"en":"What would you do if you won the lottery?","uz":"Agar lotereyada yutsangiz, nima qilgan bo''lardingiz?"}],"specialCases":[{"id":"were-subjunctive","title":"\"If I were\" — Subjunctive mayli","rule":"Second Conditional da ''I/he/she/it'' bilan ''was'' emas, ''WERE'' ishlatiladi. Bu subjunctive mayli deb ataladi.","mnemonic":"IF I WERE = har doim WERE (was emas!). ''If I were you'' — eng muhim iborani yod oling!","commonMistakes":"If I WAS you → If I WERE you. If she WAS here → If she WERE here.","examples":[{"en":"If I were you, I would accept the offer.","uz":"Men sizning o''rningizda bo''lsam, taklifni qabul qilardim."},{"en":"If she were here, she would help us.","uz":"Agar u shu yerda bo''lsa, yordam berardi."}],"drills":[{"id":46010,"type":"fill-blank","instruction":"Were bilan to''ldiring:","question":"If I ___ you, I would take that job.","blanks":["were"],"explanation":"''If I were you'' — subjunctive, always ''were''."},{"id":46011,"type":"fill-blank","instruction":"Were bilan to''ldiring:","question":"If she ___ here, she would know what to do.","blanks":["were"],"explanation":"''Were'' for all persons in unreal conditionals."},{"id":46012,"type":"error-correction","instruction":"Xatoni toping:","question":"If I was you, I would study harder.","errorPart":"was","correct":"If I were you, I would study harder.","explanation":"''If I were you'' — ''was'' emas, ''were''."}]},{"id":"first-vs-second","title":"First va Second Conditional farqi","rule":"FIRST = real, mumkin (if + Present, will + V¹). SECOND = unreal, xayoliy (if + Past, would + V¹).","mnemonic":"FIRST = REAL (will). SECOND = UNREAL (would). First bilan ''if it rains'' = haqiqiy ehtimol. Second bilan ''if it rained'' = kutilmagan.","commonMistakes":"Real vaziyatda Second ishlatish: ''If it would rain'' XATO. Yoki xayoliy vaziyatda First: ''If I will have wings'' XATO.","examples":[{"en":"First: If it rains, I will stay home. (real possibility)","uz":"Agar yomg''ir yog''sa, uyda qolaman."},{"en":"Second: If it rained, I would stay home. (unlikely)","uz":"Agar yomg''ir yog''sa (kutilmaganda), uyda qolardim."}],"drills":[{"id":46013,"type":"fill-blank","instruction":"First yoki Second:","question":"If it rains, I ___ (stay) home. (real)","blanks":["will stay"],"explanation":"Real possibility → First Conditional: ''will stay''."},{"id":46014,"type":"fill-blank","instruction":"First yoki Second:","question":"If I ___ (have) wings, I would fly. (unreal)","blanks":["had"],"explanation":"Impossible → Second Conditional: ''If I had''."},{"id":46015,"type":"multiple-choice","instruction":"First yoki Second:","question":"If I ___ the president, I would change the law.","options":["am","was","were","will be"],"correct":"were","explanation":"Unreal (I''m not president) → Second: ''If I were''."}]}],"exercises":[{"id":46020,"type":"fill-blank","instruction":"Second Conditional bilan to''ldiring:","question":"If I ___ (have) more money, I would buy a car.","blanks":["had"],"explanation":"''If I had'' — Past Simple in the if-clause."},{"id":46021,"type":"fill-blank","instruction":"Second Conditional bilan to''ldiring:","question":"If she ___ (live) near here, we would meet every day.","blanks":["lived"],"explanation":"''If she lived'' — unreal situation."},{"id":46022,"type":"fill-blank","instruction":"Second Conditional bilan to''ldiring:","question":"I ___ (travel) more if I had more vacation time.","blanks":["would travel"],"explanation":"Result: ''would travel'' — would + V¹."},{"id":46023,"type":"fill-blank","instruction":"Second Conditional bilan to''ldiring:","question":"If they ___ (not/work) so hard, they would relax more.","blanks":["didn''t work"],"explanation":"Negative if-clause: ''didn''t work''."},{"id":46024,"type":"fill-blank","instruction":"Second Conditional bilan to''ldiring:","question":"She ___ (be) happier if she lived near the sea.","blanks":["would be"],"explanation":"Result: ''would be'' — would + be."},{"id":46025,"type":"fill-blank","instruction":"If I were you:","question":"If I ___ (be) you, I would take that opportunity.","blanks":["were"],"explanation":"''If I were you'' — subjunctive ''were''."},{"id":46026,"type":"fill-blank","instruction":"Could bilan:","question":"If I spoke English fluently, I ___ (could) work abroad.","blanks":["could"],"explanation":"''Could'' = would be able to. Ability in unreal situations."},{"id":46027,"type":"fill-blank","instruction":"Second Conditional:","question":"What ___ you do if you won the lottery?","blanks":["would"],"explanation":"Question form: ''What would you do if...?''"},{"id":46028,"type":"fill-blank","instruction":"Inversion bilan:","question":"___ I rich, I would help the poor.","blanks":["Were"],"explanation":"Inversion: ''Were I rich'' = ''If I were rich''."},{"id":46029,"type":"fill-blank","instruction":"Second Conditional:","question":"If we ___ (know) the truth, we would tell you.","blanks":["knew"],"explanation":"''If we knew'' — unreal, we don''t know."},{"id":46030,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"If I ___ you, I would apologize.","options":["am","was","were","will be"],"correct":"were","explanation":"''If I were you'' — fixed expression with subjunctive ''were''."},{"id":46031,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"If she ___ more time, she would learn a new language.","options":["has","had","would have","will have"],"correct":"had","explanation":"Second conditional: if + Past Simple = ''had''."},{"id":46032,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"Where would you live if you ___ choose any city?","options":["can","could","will","would"],"correct":"could","explanation":"''Could'' in if-clause: ''if you could choose'' (ability)."},{"id":46033,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"If I ___ a bird, I would fly to you.","options":["am","was","were","will be"],"correct":"were","explanation":"Unreal (I''m not a bird) → ''If I were''."},{"id":46034,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"Which is SECOND Conditional?","options":["If it rains, I will stay","If it rained, I would stay","If it rains, I stay","If it rained, I stayed"],"correct":"If it rained, I would stay","explanation":"Second = if + Past Simple + would + V¹."},{"id":46035,"type":"error-correction","instruction":"Xatoni toping:","question":"If I would have more time, I would travel.","errorPart":"would have","correct":"If I had more time, I would travel.","explanation":"''If'' qismida ''would'' ishlatilmaydi → ''had''."},{"id":46036,"type":"error-correction","instruction":"Xatoni toping:","question":"If I was you, I would study more.","errorPart":"was","correct":"If I were you, I would study more.","explanation":"''If I were you'' — subjunctive ''were''."},{"id":46037,"type":"error-correction","instruction":"Xatoni toping:","question":"If she knew the answer, she will tell us.","errorPart":"will tell","correct":"If she knew the answer, she would tell us.","explanation":"Second Conditional → ''would tell'', not ''will tell''."},{"id":46038,"type":"error-correction","instruction":"Xatoni toping:","question":"If they will invite me, I would go.","errorPart":"will invite","correct":"If they invited me, I would go.","explanation":"If-clause → Past Simple ''invited'', not ''will invite''."},{"id":46039,"type":"transformation","instruction":"Second Conditional ga o''tkazing:","question":"I don''t have a car, so I can''t drive to work.","hint":"If I had a car...","correct":"If I had a car, I would drive to work.","explanation":"Real → unreal: ''don''t have'' → ''had'', ''can''t drive'' → ''would drive''."},{"id":46040,"type":"transformation","instruction":"Second Conditional ga o''tkazing:","question":"She doesn''t live near me, so we don''t meet often.","hint":"If she lived...","correct":"If she lived near me, we would meet often.","explanation":"''Doesn''t live'' → ''lived'', ''don''t meet'' → ''would meet''."},{"id":46041,"type":"transformation","instruction":"If I were you bilan yozing:","question":"Advice: You should apply for that job.","hint":"If I were you...","correct":"If I were you, I would apply for that job.","explanation":"''You should'' → ''If I were you, I would''."},{"id":46042,"type":"transformation","instruction":"Inversion bilan yozing:","question":"If I were rich, I would help everyone.","hint":"Were I...","correct":"Were I rich, I would help everyone.","explanation":"Inversion: drop ''if'', put ''were'' first."},{"id":46043,"type":"transformation","instruction":"Second Conditional savol:","question":"Imagine: you find a wallet. What do you do?","hint":"What would you do if...","correct":"What would you do if you found a wallet?","explanation":"Question: ''What would you do if + Past Simple?''"},{"id":46044,"type":"fill-blank","instruction":"First vs Second aralash:","question":"If it ___ (rain) tomorrow, I will stay home. If I ___ (be) you, I would take an umbrella.","blanks":["rains","were"],"explanation":"First: real possibility (rains). Second: advice (were)."},{"id":46045,"type":"fill-blank","instruction":"Second bilan aralash:","question":"If I ___ (have) wings, I ___ (fly). If she ___ (be) here, she would help.","blanks":["had","would fly","were"],"explanation":"Unreal: had + would fly, were (subjunctive)."}],"exerciseSections":[{"ids":[46020,46021,46022,46023,46024,46025,46026,46027,46028,46029],"desc":"Fill-blank asosiy","icon":"🌱","color":"bg-emerald-500","title":"Boshlang''ich"},{"ids":[46030,46031,46032,46033,46034],"desc":"MCQ tanlash","icon":"📘","color":"bg-blue-500","title":"O''rtacha"},{"ids":[46035,46036,46037,46038],"desc":"Xato tuzatish","icon":"🎯","color":"bg-violet-500","title":"Qiyin"},{"ids":[46039,46040,46041,46042,46043],"desc":"Transformatsiya","icon":"🔄","color":"bg-rose-500","title":"Transformatsiya"},{"title":"🔀 Aralash","desc":"First + Second + Inversion","color":"bg-fuchsia-500","icon":"🔄","ids":[46044,46045]}],"tests":[{"id":46050,"type":"multiple-choice","instruction":"Asosiy:","question":"Second Conditional qanday tuziladi?","options":["If + Present, will + V¹","If + Past, would + V¹","If + Past Perfect, would have + V³","If + Present, would + V¹"],"correct":"If + Past, would + V¹","explanation":"Second = If + Past Simple + would + V¹."},{"id":46051,"type":"multiple-choice","instruction":"Asosiy:","question":"''If I were you'' qanday ma''noda ishlatiladi?","options":["Taxmin","Maslahat","Buyruq","So''roq"],"correct":"Maslahat","explanation":"''If I were you'' = maslahat berish uchun."},{"id":46052,"type":"multiple-choice","instruction":"Asosiy:","question":"Second Conditional da ''I'' bilan qaysi shakl ishlatiladi?","options":["was","were","am","is"],"correct":"were","explanation":"Subjunctive: ''were'' for all persons."},{"id":46053,"type":"multiple-choice","instruction":"Asosiy:","question":"Second Conditional qachon ishlatiladi?","options":["Real vaziyatlar","Xayoliy vaziyatlar","O''tmishdagi vaziyatlar","Kelajakdagi aniq rejalar"],"correct":"Xayoliy vaziyatlar","explanation":"Second = unreal/hypothetical situations."},{"id":46054,"type":"multiple-choice","instruction":"Asosiy:","question":"Natija qismida qaysi modal fe''l ishlatiladi?","options":["will","would","can","must"],"correct":"would","explanation":"Result clause: ''would + V¹''."},{"id":46055,"type":"multiple-choice","instruction":"O''rtacha:","question":"If I ___ more free time, I would learn to paint.","options":["have","had","would have","will have"],"correct":"had","explanation":"If-clause → Past Simple ''had''."},{"id":46056,"type":"multiple-choice","instruction":"O''rtacha:","question":"She ___ happier if she lived near her family.","options":["will be","would be","is","was"],"correct":"would be","explanation":"Result: ''would be''."},{"id":46057,"type":"multiple-choice","instruction":"O''rtacha:","question":"What would you do if you ___ a million dollars?","options":["win","won","would win","will win"],"correct":"won","explanation":"If-clause → ''won'' (Past Simple)."},{"id":46058,"type":"multiple-choice","instruction":"O''rtacha:","question":"If I ___ you, I wouldn''t go there.","options":["am","was","were","will be"],"correct":"were","explanation":"''If I were you'' — fixed expression."},{"id":46059,"type":"multiple-choice","instruction":"O''rtacha:","question":"First vs Second: Which is correct for an unreal situation?","options":["If it rains, I will stay","If it rained, I would stay","If it rained, I will stay","If it rains, I would stay"],"correct":"If it rained, I would stay","explanation":"Second = if + Past + would + V¹ (unreal)."},{"id":46060,"type":"multiple-choice","instruction":"Qiyin:","question":"Qaysi gapda xato bor?","options":["If I had time, I would help","If I were you, I would go","If I would have money, I would buy","If she knew, she would tell"],"correct":"If I would have money, I would buy","explanation":"''If'' qismida ''would'' ishlatilmaydi → ''If I had money''."},{"id":46061,"type":"multiple-choice","instruction":"Qiyin:","question":"Qaysi gap Inversion bilan TO''G''RI tuzilgan?","options":["Were I rich, I would travel","Were I would be rich, I travel","I were rich, I would travel","Were rich I, would travel"],"correct":"Were I rich, I would travel","explanation":"Inversion: ''Were I rich'' = ''If I were rich''."},{"id":46062,"type":"multiple-choice","instruction":"Qiyin:","question":"''If I could fly'' qanday ma''noni bildiradi?","options":["Ucha olaman","Ucha olmayman (xayol)","Uchganman","Uchamiz"],"correct":"Ucha olmayman (xayol)","explanation":"Second Conditional → hozir ucha olmayman degani."},{"id":46063,"type":"multiple-choice","instruction":"Murakkab:","question":"Qaysi gap Second Conditional qoidasiga TO''LIQ mos keladi?","options":["If I will be rich I help poor","If I was you I will study","If I had more time I would travel the world","If I have money I travel"],"correct":"If I had more time I would travel the world","explanation":"If + Past (had) + would + V¹ (would travel). Perfect Second Conditional."}],"testSections":[{"ids":[46050,46051,46052,46053,46054],"desc":"Asosiy qoidalar","icon":"🌱","color":"bg-emerald-500","title":"Oson"},{"ids":[46055,46056,46057,46058,46059],"desc":"Qo''llash","icon":"📘","color":"bg-blue-500","title":"O''rtacha"},{"ids":[46060,46061,46062],"desc":"Tahlil","icon":"🎯","color":"bg-violet-500","title":"Qiyin"},{"ids":[46063],"desc":"Yakuniy test","icon":"🏆","color":"bg-rose-500","title":"Murakkab"}],"reading":{"passage":"What If...?\n\nImagine a world where things were different. If people had more compassion, there would be less conflict. If everyone shared what they had, nobody would go hungry. If children everywhere had access to education, the world would be a better place.\n\nOn a personal level, think about your own ''what if'' moments. If I had more confidence, I would speak English more often. If I practiced every day, I would improve quickly. If I weren''t afraid of making mistakes, I would talk to foreigners.\n\nWhat would you do if you could change one thing about your life? If I could live anywhere in the world, I would choose a city by the sea. If I spoke three languages, I could work in any country. If I were a billionaire, I would build schools in every village.\n\nThe beauty of the Second Conditional is that it lets us dream. It allows us to imagine different realities. And sometimes, imagining a different reality helps us take the first step toward making it real. If you started today, what would you achieve?","questions":[{"id":46070,"type":"multiple-choice","question":"What would happen if people had more compassion?","options":["There would be more conflict","There would be less conflict","Nothing would change","People would be richer"],"correctIndex":1,"explanation":"''If people had more compassion, there would be less conflict.''"},{"id":46071,"type":"multiple-choice","question":"What would help the speaker improve English?","options":["Reading books","Practicing every day","Watching films","Writing essays"],"correctIndex":1,"explanation":"''If I practiced every day, I would improve quickly.''"},{"id":46072,"type":"multiple-choice","question":"Where would the speaker live if they could choose?","options":["In the mountains","In a city by the sea","In the countryside","In a big city"],"correctIndex":1,"explanation":"''If I could live anywhere, I would choose a city by the sea.''"},{"id":46073,"type":"multiple-choice","question":"What would the speaker build if they were a billionaire?","options":["Hospitals","Schools","Roads","Parks"],"correctIndex":1,"explanation":"''If I were a billionaire, I would build schools in every village.''"},{"id":46074,"type":"multiple-choice","question":"What does the passage say about the Second Conditional?","options":["It''s useless","It lets us dream","It''s only for exams","It''s too difficult"],"correctIndex":1,"explanation":"''The beauty of the Second Conditional is that it lets us dream.''"}]},"writing":{"prompt":"Write about what you would do in these three hypothetical situations: (1) If you won a million dollars, (2) If you could live anywhere in the world, and (3) If you could meet any famous person. Use the Second Conditional structure (If + Past Simple, would + V¹) in each sentence. Write 6-8 sentences.","wordLimit":100,"tips":["Use ''If + Past Simple'' for the condition: ''If I won...''","Use ''would + V¹'' for the result: ''I would buy...''","Use ''were'' instead of ''was'' for ''If I were...'' (subjunctive)","Give a reason for each choice to extend your answer"]},"listening":{"transcript":"Dilshod: If I had more free time, I would learn to play the guitar. But I''m so busy with work!\\nMadina: Same here. If I didn''t work so much, I would travel more. What would you do if you won the lottery?\\nDilshod: If I won the lottery, I would buy a house for my parents and travel around the world.\\nMadina: That sounds amazing. If I were rich, I would start my own business.\\nDilshod: What kind of business would you start if you had the money?\\nMadina: If I knew how to cook well, I would open a restaurant. But I don''t!\\nDilshod: If I were you, I would take cooking classes.\\nMadina: Good idea! If I had more time, I would definitely do that.\\nDilshod: If we stopped making excuses, we would achieve so much more!\\nMadina: You''re right. If we started today, we would see results in a few months.","vocabulary":[{"word":"lottery","definition":"lotereya"},{"word":"guitar","definition":"gitara"},{"word":"business","definition":"biznes, korxona"},{"word":"excuse","definition":"bahona, uzr"},{"word":"achieve","definition":"erishmoq, qo''lga kiritmoq"}],"questions":[{"id":46001,"type":"multiple-choice","question":"What would Dilshod do if he had more free time?","options":["Travel","Learn guitar","Start a business","Cook"],"correctIndex":1,"explanation":"''If I had more free time, I would learn to play the guitar.''"},{"id":46002,"type":"multiple-choice","question":"What would Madina do if she were rich?","options":["Buy a house","Travel","Start her own business","Learn guitar"],"correctIndex":2,"explanation":"''If I were rich, I would start my own business.''"},{"id":46003,"type":"true-false","question":"If Madina won the lottery, she would buy a house for her parents.","answer":false,"explanation":"It was Dilshod who said that: ''If I won the lottery, I would buy a house for my parents.''"},{"id":46004,"type":"multiple-choice","question":"What advice does Dilshod give to Madina?","options":["Work harder","If I were you, I would take cooking classes","Travel more","Save money"],"correctIndex":1,"explanation":"''If I were you, I would take cooking classes.''"},{"id":46005,"type":"multiple-choice","question":"What would happen if they stopped making excuses?","options":["Nothing","They would achieve more","They would lose their jobs","They would be bored"],"correctIndex":1,"explanation":"''If we stopped making excuses, we would achieve so much more!''"}],"difficulty":"medium","topic":"Second Conditional — xayoliy vaziyatlar"},"dialogues":[{"id":"what-if-dialogue","title":"Agar... bo''lsa nima qilarding?","context":"Ikki do''st xayoliy vaziyatlar haqida suhbatlashmoqda.","lines":[{"speaker":"Aziz","text":"If you could meet any historical figure, who would you meet?","translation":"Agar tarixiy shaxs bilan uchrasha olsang, kim bilan uchrashgan bo''larding?"},{"speaker":"Lola","text":"If I could meet anyone, I would meet Alisher Navoiy. He was a great poet!","translation":"Agar uchra olsam, Alisher Navoiy bilan uchrashardim. U buyuk shoir edi!"},{"speaker":"Aziz","text":"Interesting choice! If I had a time machine, I would travel to ancient Khiva.","translation":"Qiziqarli tanlov! Agar vaqt mashinam bo''lsa, qadimgi Xivaga sayohat qilgan bo''lardim."},{"speaker":"Lola","text":"What would you do there? I''d explore the old city if I went there.","translation":"U yerda nima qilgan bo''larding? Men borsam, eski shaharni kashf qilardim."},{"speaker":"Aziz","text":"If I were more adventurous, I''d go there right now!","translation":"Agar jasurroq bo''lsam, hozir u yerga borardim!"}]}],"culturalNotes":[{"id":"uzbek-dreams","title":"O''zbekistonda ''Agar... bo''lsa'' orzulari","description":"Second Conditional o''zbek tilida ''agar...sa edi'' bilan ifodalanadi. O''zbeklar orasida keng tarqalgan xayoliy vaziyatlar: ''Agar lotereyada yutsam, uy olardim'', ''Agar chet elga borsam, ko''p narsa o''rganardim''. Bu iboralar ingliz tilida Second Conditional bilan bir xil ishlatiladi.","icon":"💭","category":"culture"},{"id":"were-subjunctive-world","title":"Subjunctive ''were'' — dunyo tillarida","description":"Ingliz tilidagi ''If I were'' subjunctive shakli boshqa tillarda ham mavjud. Fransuz tilida ''si j''étais'' (If I were), nemis tilida ''wenn ich wäre''. O''zbek tilida bu farq yo''q — ''Agar men bo''lsam'' hamma shaxslar uchun bir xil. Shuning uchun o''zbek talabalari ko''pincha ''If I was'' deb xato qilishadi.","icon":"🌍","category":"language"}]}'::jsonb),
('phrasal-verbs-b1', 'Phrasal Verbs', 'Separable va inseparable phrasal verbs: look after, give up, put off, etc.', 'B1', 37, 'Frasal fe''llar', '{"formulas":[{"color":"green","label":"Inseparable","structure":"Verb + particle (together)\nI look after my sister."},{"color":"blue","label":"Separable (noun)","structure":"Verb + noun + particle\nI picked my friend up."},{"color":"red","label":"Separable (pronoun)","structure":"Verb + pronoun + particle\nI picked him up."},{"color":"orange","label":"Three-word phrasal verb","structure":"Verb + particle1 + particle2\nI look forward to meeting you."}],"rules":["1️⃣ PHRASAL VERBS NIMA?\n\nPhrasal verb — bu verb + particle (preposition yoki adverb) birikmasi bo''lib, yangi ma''no hosil qiladi.\n\n📌 MUHIM: Phrasal verb ma''nosi uning tarkibidagi so''zlarning ma''nosidan farq qiladi!\n  → look = qaramoq / look after = qaramoq (birovga g''amxo''rlik qilish)\n  → give = bermoq / give up = tashlamoq, voz kechmoq\n\n📌 IKKI XIL TURI BOR:\n  • Inseparable (ajralmaydigan) — particle obektdan oldin keladi\n  • Separable (ajraladigan) — noun obekt particle dan oldin yoki keyin kela oladi","2️⃣ INSEPARABLE PHRASAL VERBS\n\nInseparable phrasal verb''larda particle obektdan AYRILMAYDI — har doim birga keladi.\n\n📌 MISOLLAR:\n  • look after → I look after my sister. (Singlimga qarayman)\n  • run into → I ran into an old friend. (Eski do''stimga tasodifan duch keldim)\n  • get over → She got over her illness. (U kasalligidan tuzaldi)\n  • care for → He cares for his parents. (U ota-onasiga qaraydi)\n  • depend on → It depends on the weather. (Ob-havoga bog''liq)\n\n🔴 QOIDA: Obekt particle dan keyin keladi. Verb va particle orasiga hech narsa qo''yib bo''lmaydi.\n  ✅ I look after my sister.\n  ❌ I look my sister after.","3️⃣ SEPARABLE PHRASAL VERBS\n\nSeparable phrasal verb''larda obekt (noun) verb va particle orasiga qo''yilishi mumkin.\n\n📌 NOUN BILAN — ikki xil variant:\n  • Verb + particle + noun: Turn off the TV.\n  • Verb + noun + particle: Turn the TV off.\n\n📌 PRONOUN BILAN — DOIM verb + pronoun + particle:\n  ✅ Turn it off.\n  ❌ Turn off it.\n\n📌 MISOLLAR:\n  • pick up / put down / turn on / take off / give up\n  → Pick up the book. / Pick the book up. / Pick it up.\n  → Put on your coat. / Put your coat on. / Put it on.\n\n🔴 Pronoun bilan ALWAYS verb orasida!","4️⃣ COMMON PHRASAL VERBS\n\nEng keng tarqalgan phrasal verb''lar:\n\n📌 INSEPARABLE:\n  • get along with — I get along with my colleagues.\n  • come across — I came across an interesting article.\n  • go through — She went through a difficult time.\n  • take after — He takes after his father.\n  • break down — The car broke down on the highway.\n\n📌 SEPARABLE:\n  • find out — Find out the truth. / Find the truth out.\n  • bring up — She brought up three children. / She brought them up.\n  • carry out — Carry out the plan. / Carry it out.\n  • put away — Put away your toys. / Put them away.\n\n📌 THREE-WORD (doim inseparable):\n  • look forward to — I look forward to meeting you.\n  • put up with — I can''t put up with this noise.\n  • run out of — We ran out of milk.\n  • look up to — I look up to my teacher.\n  • come up with — She came up with a great idea.","5️⃣ PHRASAL VERBS IN CONTEXT\n\n📌 KONTEKST MUHIM: Phrasal verb''lar ko''p ma''noli bo''lishi mumkin. Ma''no kontekstga qarab tushuniladi.\n  • give up = tashlamoq: I gave up smoking. (Chekishni tashladim)\n  • give up = topshirmoq: He gave up his seat. (Joyini berdi)\n\n📌 RASMIY VA NORASMIY:\n  • Norasmiy (phrasal verb): investigate → look into\n  • Rasmiy (single verb): reduce → cut down on\n  • IELTS: Rasmiy yozuvda single verb afzal, speaking da phrasal verb tabiiy\n\n📌 ESLATMA: Phrasal verb''ni noto''g''ri ishlatish — keng tarqalgan xato. Har bir phrasal verb ni inseparable yoki separable ekanini alohida o''rganing!"],"vocabulary":[{"en":"look after","uz":"qaramoq","rule":"inseparable","example":"I look after my brother."},{"en":"give up","uz":"tashlamoq, voz kechmoq","rule":"separable","example":"He gave up smoking."},{"en":"pick up","uz":"olmoq, terib olmoq","rule":"separable","example":"Pick me up at 5."},{"en":"turn off","uz":"ochirmoq","rule":"separable","example":"Turn off the TV."},{"en":"put on","uz":"kiymoq, qoymoq","rule":"separable","example":"Put on your jacket."},{"en":"take after","uz":"o''xshab ketmoq","rule":"inseparable","example":"She takes after her father."},{"en":"run into","uz":"uchratib qolmoq (tasodifan)","rule":"inseparable","example":"I ran into Ali yesterday."},{"en":"get over","uz":"o''tib ketmoq (tuzalmoq)","rule":"inseparable","example":"He got over the flu."},{"en":"look forward to","uz":"intizor bolmoq","rule":"three-word","example":"I look forward to meeting you."},{"en":"put up with","uz":"chidamoq","rule":"three-word","example":"I can''t put up with this noise."},{"en":"find out","uz":"bilib olmoq","rule":"separable","example":"Find out the truth."},{"en":"bring up","uz":"tarbiyalamoq, gap ochmoq","rule":"separable","example":"She brought up three children."},{"en":"phrasal verb","uz":"fraza fe''l","rule":"core concept","example":"A phrasal verb is a verb + particle."},{"en":"particle","uz":"yuklama (preposition/adverb)","rule":"phrasal verb","example":"The particle can be up, off, on, etc."},{"en":"separable","uz":"ajratiladigan","rule":"separable","example":"Pick up is separable — pick my friend up."},{"en":"inseparable","uz":"ajratilmaydigan","rule":"inseparable","example":"Look after is inseparable — look after him."}],"examples":[{"en":"Please look after my cat while I''m away.","uz":"Men yo''qimda mushugimga qarang."},{"en":"He gave up smoking last year.","uz":"U o''tgan yili chekishni tashladi."},{"en":"Can you pick me up at the airport?","uz":"Meni aeroportda olib keta olasizmi?"},{"en":"Turn off the lights before leaving.","uz":"Ketishdan oldin chiroqni o''chiring."},{"en":"She takes after her mother.","uz":"U onasiga o''xshab ketgan."},{"en":"I ran into an old friend yesterday.","uz":"Kecha eski do stirimni uchratib qoldim."},{"en":"I''m looking forward to the weekend.","uz":"Dam olish kunini intizorlik bilan kutyapman."},{"en":"I can''t put up with this noise anymore.","uz":"Bu shovqinga boshqa chidolmayman."}],"specialCases":[{"id":"separable-vs-inseparable","rule":"SEPARABLE: noun ikkala tomonda, pronoun faqat orada. INSEPARABLE: doim birga.","title":"Separable va Inseparable farqi","drills":[{"id":45066,"type":"fill-blank","blanks":["him up"],"question":"I picked ___ (up / him / him up).","explanation":"Pronoun bilan particle birga ishlatiladi (grammatik qoida)","instruction":"Pronoun:"},{"id":45067,"type":"error-correction","correct":"Please pick me up at 5.","question":"Please pick up me at 5.","errorPart":"up me","explanation":"Pronoun -> verb orasida","instruction":"Error correction:"},{"id":45068,"type":"multiple-choice","correct":"I look after him","options":["I look after him","I look him after","I look after he","I look he after"],"question":"Which is CORRECT?","explanation":"Inseparable — ajralmas phrasal verb, o''zgarishsiz","instruction":"Tanlang:"}],"examples":[{"en":"I picked up my friend. / I picked my friend up.","uz":"Do''stimni oldim."},{"en":"I picked him up. (not: I picked up him)","uz":"Uni oldim."}],"mnemonic":"Pronoun always between verb and particle for separable","commonMistakes":"I look after him (to''g''ri). I look him after (noto''g''ri)"},{"id":"three-word-phrasal-verbs","rule":"Verb + particle1 + particle2 = doim inseparable. Obekt particle2 dan keyin.","title":"Three-word phrasal verbs","drills":[{"id":45069,"type":"fill-blank","blanks":["to"],"question":"I look forward ___ hearing from you.","explanation":"Look forward TO (ingliz tilida shunday ishlatiladi)","instruction":"Three-word:"},{"id":45070,"type":"error-correction","correct":"I look forward to meeting you.","question":"I look forward to meet you.","errorPart":"to meet","explanation":"Look forward to + -ing","instruction":"Error correction:"},{"id":45071,"type":"multiple-choice","correct":"with","options":["with","with it","it","to"],"question":"She couldnt put up ___ the noise.","explanation":"Put up WITH — chidamoq, dosh bermoq: put up with noise","instruction":"Tanlang:"}],"examples":[{"en":"I''m looking forward to meeting you.","uz":"Siz bilan uchrashishni intiqlik bilan kutyapman."},{"en":"She came up with a great idea.","uz":"U ajoyib fikr topdi."}],"mnemonic":"Verb + prep + prep = object at the end always","commonMistakes":"I look forward to meet you (meeting kerak)"},{"id":"phrasal-verb-vs-single","rule":"Phrasal verb informal, single word formal. Contextga qarab tanlanadi.","title":"Phrasal verb vs Single word verb","drills":[{"id":45072,"type":"fill-blank","blanks":["investigate"],"question":"We need to ___ (investigate/look into) the matter formally.","explanation":"Rasmiy -> single word","instruction":"Formal:"},{"id":45073,"type":"multiple-choice","correct":"looked into","options":["investigated","looked into","examined","analyzed"],"question":"Informal: The company ___ the problem.","explanation":"Phrasal = informal — tarjima","instruction":"Tanlang:"},{"id":45074,"type":"error-correction","correct":"The CEO examined the report.","question":"The CEO looked into the report formally. (too informal)","errorPart":"looked into","explanation":"Formal -> single word","instruction":"Error correction:"}],"examples":[{"en":"The police investigated the crime. (formal)","uz":"Politsiya jinoyatni tekshirdi."},{"en":"The police looked into the crime. (informal)","uz":"Politsiya jinoyatni ko''rib chiqdi."}],"mnemonic":"Phrasal = daily talk, Single = academic/formal","commonMistakes":"Rasmiy yozuvda phrasal verb ishlatish"}],"exercises":[{"id":45075,"type":"fill-blank","blanks":["look"],"question":"Please ___ after the children.","explanation":"Look after = qaramoq","instruction":"Phrasal verb:"},{"id":45076,"type":"fill-blank","blanks":["the light"],"question":"Turn ___ off before leaving.","explanation":"Turn off is separable: ''the light'' is the noun object and goes between the verb and the particle","instruction":"Object:"},{"id":45077,"type":"fill-blank","blanks":["him"],"question":"I picked ___ up at the station.","explanation":"Pronoun before up (ingliz tilida shunday ishlatiladi)","instruction":"Pronoun:"},{"id":45078,"type":"fill-blank","blanks":["after"],"question":"She takes ___ her grandmother.","explanation":"Take after = inseparable","instruction":"Inseparable:"},{"id":45079,"type":"fill-blank","blanks":["to"],"question":"I''m looking forward ___ the party.","explanation":"Look forward TO (ingliz tilida shunday ishlatiladi)","instruction":"Three-word:"},{"id":45080,"type":"fill-blank","instruction":"Tanlang:","question":"I ran ___ an old friend yesterday.","blanks":["into"],"explanation":"Run into = tasodifan uchrashish"},{"id":45081,"type":"fill-blank","instruction":"Tanlang:","question":"He gave ___ smoking last year.","blanks":["up"],"explanation":"Give up = tashlamoq — \"Give up\" so''zining tarjimasi"},{"id":45082,"type":"fill-blank","instruction":"Tanlang:","question":"Put ___ your jacket, its cold.","blanks":["on"],"explanation":"Put on = kiymoq (ingliz tilida \"kiymoq\" degan ma''no)"},{"id":45083,"type":"fill-blank","instruction":"Tanlang:","question":"I can''t put ___ with this noise.","blanks":["up"],"explanation":"Put up with = chidamoq"},{"id":45084,"type":"fill-blank","instruction":"Tanlang:","question":"She takes ___ her mother.","blanks":["after"],"explanation":"Take after = oxshamoq"},{"id":45085,"type":"error-correction","correct":"I look after my grandmother on weekends.","question":"I look my grandmother after on weekends.","errorPart":"my grandmother after","explanation":"Look after is inseparable: the object stays after the particle","instruction":"Error correction:"},{"id":45086,"type":"error-correction","correct":"Please pick me up at 5.","question":"Please pick up me at 5.","errorPart":"up me","explanation":"Pronoun -> verb + pronoun + particle","instruction":"Error correction:"},{"id":45087,"type":"error-correction","correct":"I look forward to meeting you.","question":"I look forward to meet you.","errorPart":"to meet","explanation":"Look forward to + -ing","instruction":"Error correction:"},{"id":45088,"type":"error-correction","correct":"Turn it off before leaving.","question":"Turn off it before leaving.","errorPart":"off it","explanation":"Pronoun — > orada: Pronoun > orada uchun ishlatiladi","instruction":"Error correction:"},{"id":45089,"hint":"Please...","type":"transformation","correct":"Please care for the children.","question":"Please look after the children. (use: care for)","explanation":"Synonym — sinonim, bir xil ma''noli so''z","instruction":"O''zgartiring:"},{"id":45090,"hint":"He gave...","type":"transformation","correct":"He gave up smoking.","question":"He stopped smoking. (use: give up)","explanation":"Give up = tashlamoq — \"Give up\" so''zining tarjimasi","instruction":"O''zgartiring:"},{"id":45091,"hint":"I ran...","type":"transformation","correct":"I ran into her yesterday.","question":"I met her by chance yesterday. (use: run into)","explanation":"Run into = tasodifan uchrashmoq","instruction":"O''zgartiring:"},{"id":45092,"type":"fill-blank","blanks":["up"],"question":"I picked my friend ___ after work.","explanation":"Pick up = separable — \"Pick up\" so''zining tarjimasi","instruction":"Separable:"},{"id":45093,"type":"fill-blank","blanks":["over"],"question":"He couldnt get ___ his illness quickly.","explanation":"Get over = tuzalmoq — \"Get over\" so''zining tarjimasi","instruction":"Phrasal:"},{"id":45094,"type":"multiple-choice","correct":"I look forward to meeting you","options":["I look forward to meet you","I look forward to meeting you","I look forward meet you","I look forward meeting you"],"question":"Which is CORRECT?","explanation":"Look forward to + -ing","instruction":"Tanlang:"},{"id":45095,"type":"fill-blank","blanks":["into"],"question":"I ran ___ an old friend at the market.","explanation":"Run into — tasodifan uchrashmoq: I ran into my friend","instruction":"Inseparable:"},{"id":45096,"type":"fill-blank","blanks":["out"],"question":"We need to find ___ what happened.","explanation":"Find out — aniqlamoq, bilib olmoq: I found out the truth","instruction":"Separable:"},{"id":45097,"type":"fill-blank","blanks":["through"],"question":"She has been ___ a lot lately.","explanation":"Go through — o''tmoq, tekshirmoq: Go through the gate","instruction":"Phrasal:"},{"id":45098,"type":"fill-blank","instruction":"Tanlang:","question":"Please turn ___ the TV before sleeping.","blanks":["off"],"explanation":"Turn off — o''chirmoq: Turn off the light"},{"id":45099,"type":"fill-blank","instruction":"Tanlang:","question":"We ran ___ of milk.","blanks":["out"],"explanation":"Run out of — tugamoq, kamaymoq: We ran out of milk"},{"id":45100,"type":"fill-blank","instruction":"Tanlang:","question":"She had to ___ three children alone.","blanks":["bring up"],"explanation":"Bring up — tarbiyalamoq, o''stirmoq"},{"id":45101,"type":"error-correction","correct":"He takes after his father.","question":"He takes his father after.","errorPart":"his father after","explanation":"Take after = inseparable","instruction":"Error correction:"},{"id":45102,"type":"error-correction","correct":"Turn off the lights before leaving.","question":"Turn the lights before leaving off.","errorPart":"before leaving off","explanation":"Separable: verb + particle + noun","instruction":"Error correction:"},{"id":45103,"type":"transformation","hint":"I put on...","correct":"I put on my jacket because it was cold.","question":"I put my jacket on because it was cold.","explanation":"Separable word order","instruction":"O''zgartiring:"},{"id":45104,"type":"transformation","hint":"She came up with...","correct":"She came up with a brilliant idea.","question":"She thought of a brilliant idea. (use: come up with)","explanation":"Come up with (ingliz tilida shunday ishlatiladi)","instruction":"O''zgartiring:"},{"id":45105,"type":"fill-blank","blanks":["along"],"question":"My sister and I get ___ well.","explanation":"Get along — yaxshi munosabatda bo''lmoq","instruction":"Phrasal:"},{"id":45106,"type":"fill-blank","blanks":["away"],"question":"Please put ___ your toys.","explanation":"Put away — joyiga qo''ymoq: Put away your toys","instruction":"Separable:"},{"id":45107,"type":"fill-blank","blanks":["down"],"question":"The car broke ___ on the highway.","explanation":"Break down — buzilmoq, yo''qotmoq: The car broke down","instruction":"Inseparable:"},{"id":65260,"type":"fill-blank","instruction":"Separable vs inseparable:","question":"I picked my friend ___ after work. I look ___ my sister on weekends.","blanks":["up","after"],"explanation":"Pick up = separable (noun can go between). Look after = inseparable (always together)."},{"id":65261,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"Which is CORRECT? Pick ___ up at 5.","options":["me","Pick me up","up me","me up"],"correct":"me","explanation":"Pronoun always goes between verb and particle for separable phrasal verbs."},{"id":65262,"type":"error-correction","instruction":"Phrasal verb word order:","question":"Please pick up me at 5. I look forward to meet you.","errorPart":"up me / to meet","correct":"Please pick me up at 5. I look forward to meeting you.","explanation":"Pronoun = verb + pronoun + particle. Look forward to + V-ing."},{"id":65263,"type":"fill-blank","instruction":"Three-word phrasal verbs:","question":"I look forward ___ hearing from you. She came up ___ a great idea. We ran out ___ milk.","blanks":["to","with","of"],"explanation":"Three-word phrasal verbs: look forward to, come up with, run out of."},{"id":65264,"type":"transformation","instruction":"Formal to phrasal:","question":"I cannot tolerate this noise anymore. (use: put up with)","hint":"I cannot...","correct":"I cannot put up with this noise anymore.","explanation":"Tolerate = formal. Put up with = phrasal verb (informal)."}],"exerciseSections":[{"ids":[2801,2802,2803,2804,2805],"desc":"Basic phrasal verbs","icon":"F1","color":"bg-emerald-500","title":"Boshlangich"},{"ids":[2806,2807,2808,2809,2810],"desc":"MCQ","icon":"B8","color":"bg-blue-500","title":"Ortacha"},{"ids":[2811,2812,2813,2814,2815],"desc":"Error correction","icon":"AA","color":"bg-violet-500","title":"Qiyin"},{"ids":[2816,2817,2818,2819,2820,2821,2822,2823,2824,2825,2826,2827,2828,2829,2830,2831,2832,2833],"desc":"Transformation + Qo''shimcha","icon":"C6","color":"bg-rose-500","title":"Murakkab"},{"title":"🔀 Aralash","desc":"Phrasal verbs + Separable/Inseparable farqi","color":"bg-fuchsia-500","icon":"🔄","ids":[95611,95612,95613,95614,95615]}],"tests":[{"id":45108,"type":"multiple-choice","correct":"qaramoq","options":["qaramoq","qidirmoq","kuzatmoq","topmoq"],"question":"What does ''look after'' mean?","explanation":"Look after = to take care of","instruction":"Asosiy"},{"id":45109,"type":"multiple-choice","correct":"tashlamoq","options":["bermoq","tashlamoq","olmoq","ochmoq"],"question":"What does ''give up'' mean?","explanation":"Give up = to stop or quit","instruction":"Asosiy"},{"id":45110,"type":"multiple-choice","correct":"uchratib qolmoq","options":["yugurmoq","kirib ketmoq","uchratib qolmoq","topmoq"],"question":"What does ''run into'' mean?","explanation":"Run into = to meet unexpectedly","instruction":"Asosiy"},{"id":45111,"type":"multiple-choice","correct":"ha","options":["ha","yoq","ba''zan","three-word"],"question":"Is ''give up'' separable?","explanation":"Give up = separable — \"Give up\" so''zining tarjimasi","instruction":"Asosiy"},{"id":45112,"type":"multiple-choice","correct":"inseparable","options":["separable","inseparable","three-word","none"],"question":"Is ''look after'' separable or inseparable?","explanation":"Look after = inseparable","instruction":"Asosiy"},{"id":45113,"type":"multiple-choice","correct":"into","options":["after","into","over","through"],"question":"I ran ___ an old friend.","explanation":"Run into — tasodifan uchrashmoq: I ran into my friend","instruction":"Ortacha"},{"id":45114,"type":"multiple-choice","correct":"up","options":["in","up","out","off"],"question":"He gave ___ smoking.","explanation":"Give up — voz kechmoq, tashlamoq: Don''t give up","instruction":"Ortacha"},{"id":45115,"type":"multiple-choice","correct":"on","options":["off","on","down","away"],"question":"Put ___ your jacket.","explanation":"Put on — kiyinmoq: Put on your coat","instruction":"Ortacha"},{"id":45116,"type":"multiple-choice","correct":"with","options":["for","with","to","at"],"question":"I put up ___ the noise.","explanation":"Put up with — chidamoq, dosh bermoq: I can''t put up with noise","instruction":"Ortacha"},{"id":45117,"type":"multiple-choice","correct":"after","options":["after","over","up","in"],"question":"She takes ___ her father.","explanation":"Take after — o''xshamoq, taqlid qilmoq: She takes after her mother","instruction":"Ortacha"},{"id":45118,"type":"multiple-choice","correct":"Yes, pronoun","options":["Yes, pronoun","Yes, noun","No","Three-word"],"question":"Pick me up -> separable?","explanation":"Pronoun — > orada: Pronoun > orada uchun ishlatiladi","instruction":"Qiyin"},{"id":45119,"type":"multiple-choice","correct":"look after him","options":["pick him up","look after him","turn it on","give it up"],"question":"Inseparable pronoun?","explanation":"Look after = inseparable","instruction":"Qiyin"},{"id":45120,"type":"multiple-choice","correct":"look forward to","options":["look after","give up","look forward to","pick up"],"question":"Three-word phrasal verb?","explanation":"Three-word — uch so''zli phrasal verb: look forward to","instruction":"Qiyin"},{"id":45121,"type":"multiple-choice","correct":"Pick me up","options":["Pick up me","Pick me up","Pick up I","Pick I up"],"question":"Which is CORRECT?","explanation":"Pronoun — > orada: Pronoun > orada uchun ishlatiladi","instruction":"Murakkab"},{"id":45122,"type":"multiple-choice","correct":"The CEO investigated the matter","options":["The CEO looked into the matter","The CEO investigated the matter","The CEO checked out the matter","The CEO looked at the matter"],"question":"Which is CORRECT formal?","explanation":"Rasmiy -> single word","instruction":"Murakkab"}],"testSections":[{"ids":[45111,45112,45113,45114,45115],"desc":"Meanings","icon":"F1","color":"bg-emerald-500","title":"Oson"},{"ids":[45116,45117,45118,45119,45120],"desc":"Qollash","icon":"B8","color":"bg-blue-500","title":"Ortacha"},{"ids":[291,292,293],"desc":"Separable/Inseparable","icon":"AA","color":"bg-violet-500","title":"Qiyin"},{"ids":[45121,45122],"desc":"Sinov","icon":"C6","color":"bg-rose-500","title":"Murakkab"}],"reading":{"passage":"Phrasal Verbs in Daily Life\n\nUlug''bek is telling his friend Sarvar about his day.\n\n\"I woke up late this morning. I had to hurry up and get ready quickly. I picked up my bag and ran out of the house.\"\n\nSarvar asks: \"Did you have breakfast?\"\n\"No, I didn''t. I stopped at the bakery and picked up a sandwich. I looked after my little brother yesterday, so I was tired.\"\n\n\"What about the meeting?\" asks Sarvar.\n\"Oh, I had to put off the meeting until next week. The manager couldn''t come. We need to find out what happened.\"\n\n\"And tonight?\"\n\"I''m looking forward to the concert. I''ll pick up my friend at 7. We''re going to have a great time!\"\n\n\"Don''t stay out late,\" says Sarvar. \"You shouldn''t give up sleep.\"\n\"Don''t worry, I''ll turn in early tomorrow. I can''t put up with being tired all the time!\"","questions":[{"id":45123,"type":"multiple-choice","question":"What does Ulug''bek mean by ''hurry up''?","options":["Slow down","Move quickly","Give up","Turn off"],"correctIndex":1,"explanation":"''Hurry up'' = tezlash, shoshilmoq."},{"id":45124,"type":"multiple-choice","question":"What did Ulug''bek pick up at the bakery?","options":["A book","A sandwich","A friend","His brother"],"correctIndex":1,"explanation":"''Pick up'' = olib kelmoq, sotib olmoq."},{"id":45125,"type":"multiple-choice","question":"Why did Ulug''bek put off the meeting?","options":["He was sick","The manager couldn''t come","He forgot","It was cancelled"],"correctIndex":1,"explanation":"''Put off'' = kechiktirmoq."},{"id":45126,"type":"multiple-choice","question":"What is Ulug''bek looking forward to?","options":["Work","A concert","Sleep","A meeting"],"correctIndex":1,"explanation":"''Look forward to'' = intizor bolmoq."},{"id":45127,"type":"multiple-choice","question":"What does Sarvar mean by ''give up sleep''?","options":["Sleep more","Stop sleeping","Lose sleep","Wake up early"],"correctIndex":2,"explanation":"''Give up'' = voz kechmoq, tashlamoq."}]},"listening":{"transcript":"Mum: Please turn off the TV and clean up your room.\nSon: OK. Can I go out after?\nMum: Yes, but be back by six. Don''t stay out late.\nSon: Sure. I''ll pick up some bread on the way home.\nMum: Good. And don''t forget to take out the rubbish.\nSon: I won''t. By the way, my friend is coming over tonight.\nMum: That''s fine. Just tidy up afterwards.\nSon: Of course. Can you wake me up early tomorrow?\nMum: Yes. Now hurry up — we''re running out of time!\nSon: OK, I''m getting ready now.","vocabulary":[{"word":"turn off","definition":"o''chirmoq"},{"word":"clean up","definition":"tozalamoq, yig''ishtirmoq"},{"word":"pick up","definition":"olib kelmoq, ko''tarmoq"},{"word":"take out","definition":"tashqariga chiqarmoq"},{"word":"hurry up","definition":"shoshilmoq"}],"questions":[{"id":90821,"type":"multiple-choice","question":"What does Mum ask the son to turn off?","options":["The light","The TV","The radio","The computer"],"correctIndex":1,"explanation":"''turn off the TV'' — phrasal verb (separable)."},{"id":90822,"type":"multiple-choice","question":"By what time must the son be back?","options":["Five","Six","Seven","Eight"],"correctIndex":1,"explanation":"''be back by six.'' (ingliz tili qoidasi)"},{"id":90823,"type":"multiple-choice","question":"What will the son pick up on the way home?","options":["Milk","Bread","Fruit","A newspaper"],"correctIndex":1,"explanation":"''I''ll pick up some bread on the way home.''"},{"id":90824,"type":"true-false","question":"A friend is coming over tonight.","answer":true,"explanation":"''my friend is coming over tonight'' — come over = visit."},{"id":90825,"type":"multiple-choice","question":"What does the son ask Mum to do tomorrow?","options":["Cook breakfast","Wake him up early","Drive him","Buy bread"],"correctIndex":1,"explanation":"''Can you wake me up early tomorrow?''"}],"difficulty":"medium","topic":"Phrasal fe''llar — turn off / clean up / pick up / take out"}}'::jsonb),
('basic-relative-clauses-a2', 'Basic Relative Clauses', 'Who, which, that, where, when — nisbiy gaplar bilan tanishtirish', 'A2', 55, 'Gap tuzilishi', '{"formulas":[{"color":"green","label":"Who — odamlar uchun","structure":"Noun + who + verb\n  The woman who lives next door is kind.","explanation":"''Who'' odamlar (people) uchun ishlatiladi. Relative clause ichida ega (subject) vazifasida bo''ladi.","whenToUse":"Biror odam haqida qo''shimcha ma''lumot berishda. ''Who'' dan keyin fe''l keladi.","example":"The girl who sings very well is my friend. (Juda yaxshi kuylaydigan qiz mening do''stim)"},{"color":"blue","label":"Which — narsalar uchun","structure":"Noun + which + verb\n  The book which I read was interesting.","explanation":"''Which'' narsalar (things) va hayvonlar uchun ishlatiladi. Relative clause ichida ega yoki obekt bo''lishi mumkin.","whenToUse":"Biror narsa yoki hayvon haqida qo''shimcha ma''lumot berishda.","example":"The car which is parked outside is mine. (Tashqarida to''xtab turgan mashina meniki)"},{"color":"purple","label":"That — odam va narsalar uchun","structure":"Noun + that + verb\n  The man that called you is my brother.","explanation":"''That'' odamlar va narsalar uchun ishlatiladi. Defining relative clauses da ''who'' va ''which'' o''rnini bosishi mumkin.","whenToUse":"Defining relative clause da who yoki which o''rniga ishlatsa bo''ladi. Norasmiy nutqda keng tarqalgan.","example":"The movie that we watched was fantastic. (Biz ko''rgan film ajoyib edi)"},{"color":"orange","label":"Where — joylar uchun","structure":"Noun (place) + where + subject + verb\n  The park where children play is beautiful.","explanation":"''Where'' joylar (places) uchun ishlatiladi. ''Where'' dan keyin to''liq gap (subject + verb) keladi.","whenToUse":"Biror joy haqida qo''shimcha ma''lumot berishda: the city where, the restaurant where, the school where.","example":"I remember the school where I studied. (Men o''qigan maktabni eslayman)"},{"color":"red","label":"When — vaqt uchun","structure":"Noun (time) + when + subject + verb\n  I remember the day when we met.","explanation":"''When'' vaqt (time) uchun ishlatiladi. ''When'' dan keyin to''liq gap keladi.","whenToUse":"Biror vaqt haqida gapirganda: the day when, the year when, the moment when.","example":"Summer is the season when I travel. (Yoz — men sayohat qiladigan fasl)"}],"rules":["1️⃣ RELATIVE CLAUSES NIMA?\n\nRelative clauses (nisbiy gaplar) — bir ot haqida qo''shimcha ma''lumot beradi. Relative clause ot dan KEYIN keladi.\n\n  → The woman who lives next door is a doctor.\n  → ''Who lives next door'' = relative clause → ''the woman'' haqida ma''lumot\n\n📌 A2 darajasida faqat DEFINING relative clauses o''rganiladi — ular gap ma''nosi uchun zarur va vergulsiz yoziladi.","2️⃣ WHO — ODMALAR UCHUN\n\n''Who'' odamlar (people) uchun ishlatiladi. Relative clause ichida ega (subject) vazifasida bo''ladi.\n  → The man who called you is my brother. (Sizga qo''ng''iroq qilgan odam mening akam)\n  → I know a girl who can speak five languages. (Men besh tilda gapira oladigan qizni bilaman)\n  → The student who won the prize is my friend. (Mukofotni yutgan talaba mening do''stim)\n\n🔴 ''Who'' dan keyin FE''L keladi (chunki who = ega): who called, who lives, who won","3️⃣ WHICH — NARSALAR UCHUN\n\n''Which'' narsalar (things) va hayvonlar uchun ishlatiladi.\n  → The book which I bought is very interesting. (Men sotib olgan kitob juda qiziqarli)\n  → The car which is parked outside is red. (Tashqarida to''xtab turgan mashina qizil)\n  → I like the music which you played. (Sen qo''ygan musiqa menga yoqadi)\n\n🔴 Who = odamlar, Which = narsalar. Aralashtirmang!","4️⃣ THAT — ODMALAR VA NARSALAR UCHUN\n\n''That'' odamlar va narsalar uchun ishlatiladi — ''who'' va ''which'' o''rnini bosishi mumkin.\n  → Who o''rniga: The woman that lives next door...\n  → Which o''rniga: The book that I bought...\n  → The dog that is barking is ours. (Hurigan kuchuk bizniki)\n\n📌 ''That'' faqat DEFINING relative clause da ishlatiladi. Non-defining da ishlatilmaydi.\n📌 A2 darajasida ''that'' eng ko''p ishlatiladigan relative pronoun hisoblanadi.","5️⃣ WHERE — JOYLAR UCHUN\n\n''Where'' joylar (places) uchun ishlatiladi.\n  → The town where I grew up is very small. (Men o''sgan shaharcha juda kichkina)\n  → Is this the restaurant where we ate last week? (Bu biz o''tgan hafta ovqatlangan restoranmi?)\n  → I love the park where children play. (Bolalar o''ynaydigan bog''ni yaxshi ko''raman)\n\n📌 ''Where'' dan keyin to''liq gap keladi: where + subject + verb","6️⃣ WHEN — VAQT UCHUN\n\n''When'' vaqt (time) uchun ishlatiladi.\n  → I remember the day when we first met. (Birinchi marta uchrashgan kunimizni eslayman)\n  → Autumn is the season when leaves fall. (Kuz — barglar to''kiladigan fasl)\n  → Do you remember the year when we travelled to Samarkand? (Samarqandga sayohat qilgan yilni eslaysanmi?)\n\n📌 ''When'' dan keyin to''liq gap keladi: when + subject + verb","7️⃣ MUHIM QOIDA: Subject vs Object\n\nAgar relative pronoun dan keyin FE''L kelsa → pronoun ega (subject):\n  → The woman who LIVES next door... (''who'' = ega, ''lives'' = fe''l)\n  → Pronounni tushirib BO''LMAYDI: The woman lives next door... → XATO\n\nAgar relative pronoun dan keyin OT/OLMOSH kelsa → pronoun obekt (object):\n  → The book which I READ... (''which'' = obekt, ''I'' = ega)\n  → Pronounni tushirish MUMKIN: The book I read... → TO''G''RI\n\n🔴 Qoida: Pronoun + verb = subject (tushirilmaydi) / Pronoun + noun/pronoun = object (tushirilishi mumkin)","8️⃣ O''ZBEKCHA XATOLAR\n\n📌 ''Who'' va ''which'' ni aralashtirish:\n  ❌ The book who I read was good.\n  ✅ The book which I read was good.\n\n📌 ''What'' ni nisbiy olmosh sifatida ishlatish:\n  ❌ The woman what lives next door...\n  ✅ The woman who lives next door...\n\n📌 Relative clausedan keyin takrorlash:\n  ❌ The woman who she lives next door...\n  ✅ The woman who lives next door... (she kerak emas!)\n\n📌 Subject pronounni tushirish:\n  ❌ The woman lives next door is a nurse.\n  ✅ The woman who lives next door is a nurse."],"vocabulary":[{"en":"who","uz":"kimki (odamlar)","example":"The woman who lives next door is kind.","rule":"people"},{"en":"which","uz":"qaysiki (narsalar)","example":"The book which I read was good.","rule":"things"},{"en":"that","uz":"kimki / qaysiki","example":"The movie that we watched was fun.","rule":"people and things"},{"en":"where","uz":"qayerda (joy)","example":"The park where we play is big.","rule":"places"},{"en":"when","uz":"qachon (vaqt)","example":"The day when we met was sunny.","rule":"time"},{"en":"relative clause","uz":"nisbiy gap","example":"A relative clause gives extra information about a noun.","rule":"grammar concept"},{"en":"relative pronoun","uz":"nisbiy olmosh","example":"Who, which, that, where, when are relative pronouns.","rule":"grammar concept"},{"en":"person","uz":"odam, shaxs","example":"The person who called you is waiting.","rule":"people"},{"en":"thing","uz":"narsa","example":"The thing which I like most is music.","rule":"things"},{"en":"place","uz":"joy, o''rin","example":"This is the place where I was born.","rule":"places"},{"en":"time","uz":"vaqt","example":"Tell me the time when you usually wake up.","rule":"time"},{"en":"information","uz":"ma''lumot","example":"The relative clause adds information about the noun.","rule":"grammar concept"},{"en":"connect","uz":"bog''lamoq","example":"Relative pronouns connect two ideas.","rule":"grammar concept"},{"en":"describe","uz":"ta''riflamoq","example":"Relative clauses describe nouns.","rule":"grammar concept"},{"en":"extra","uz":"qo''shimcha","example":"The relative clause gives extra information.","rule":"grammar concept"}],"examples":[{"en":"The man who lives next door is a doctor.","uz":"Yon qo''shnimizda yashaydigan odam shifokor."},{"en":"The book which I bought was very interesting.","uz":"Men sotib olgan kitob juda qiziqarli edi."},{"en":"The girl that sings beautifully is my cousin.","uz":"Go''zal kuylaydigan qiz mening amakivachcham."},{"en":"The park where children play is near my house.","uz":"Bolalar o''ynaydigan bog'' uyimga yaqin."},{"en":"I remember the day when we first met.","uz":"Birinchi marta uchrashgan kunimizni eslayman."},{"en":"She is the teacher who helped me a lot.","uz":"U menga ko''p yordam bergan o''qituvchi."},{"en":"This is the restaurant which serves the best plov.","uz":"Bu eng yaxshi palov tayyorlaydigan restoran."},{"en":"Summer is the season when I go to the beach.","uz":"Yoz — men dengizga boradigan fasl."}],"specialCases":[{"id":"who-vs-which","title":"Who va Which farqi","rule":"WHO = odamlar (people). WHICH = narsalar (things). THAT = ikkalasi uchun. Doim otning ma''nosiga qarab tanlang.","mnemonic":"WHO = Who is a person? → odam. WHICH = Which is a thing? → narsa. THAT = har ikkalasi.","commonMistakes":"The book who I read XATO (which/that kerak). The woman which lives XATO (who/that kerak).","examples":[{"en":"The woman who called you is my aunt. (person → who)","uz":"Sizga qo''ng''iroq qilgan ayol mening xolam."},{"en":"The letter which arrived today is from him. (thing → which)","uz":"Bugun kelgan xat undan."},{"en":"The friend that helped me is very kind. (person → that)","uz":"Menga yordam bergan do''st juda mehribon."}],"drills":[{"id":77010,"type":"fill-blank","instruction":"Who yoki which bilan to''ldiring:","question":"The woman ___ called you is my aunt.","blanks":["who"],"explanation":"''Woman'' = person → ''who''."},{"id":77011,"type":"fill-blank","instruction":"Who yoki which bilan to''ldiring:","question":"The book ___ I read was boring.","blanks":["which"],"explanation":"''Book'' = thing → ''which''."},{"id":77012,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"The car ___ is parked outside is red.","options":["who","which","whose","whom"],"correct":"which","explanation":"''Car'' = thing → ''which''."},{"id":77013,"type":"error-correction","instruction":"Xatoni toping va to''g''rilang:","question":"The girl which lives next door is friendly.","errorPart":"which","correct":"The girl who lives next door is friendly.","explanation":"''Girl'' = person → ''who'', not ''which''."},{"id":77014,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"I know a man ___ can speak five languages.","options":["which","who","where","when"],"correct":"who","explanation":"''Man'' = person → ''who''."}]},{"id":"where-and-when","title":"Where va When ishlatilishi","rule":"WHERE = joy (park, city, restaurant). WHEN = vaqt (day, year, summer, moment).","mnemonic":"WHERE = location → ''here'' so''zida ''here'' bor. WHEN = time → ''then'' so''zida ''hen'' (when) bor.","commonMistakes":"The restaurant when we ate XATO (where kerak). The summer where I travelled XATO (when kerak).","examples":[{"en":"This is the school where I study.","uz":"Bu men o''qiydigan maktab."},{"en":"Winter is the season when it snows.","uz":"Qish — qor yog''adigan fasl."}],"drills":[{"id":77015,"type":"fill-blank","instruction":"Where yoki when bilan to''ldiring:","question":"This is the park ___ we play football.","blanks":["where"],"explanation":"''Park'' = place → ''where''."},{"id":77016,"type":"fill-blank","instruction":"Where yoki when bilan to''ldiring:","question":"Sunday is the day ___ we relax.","blanks":["when"],"explanation":"''Day'' = time → ''when''."},{"id":77017,"type":"error-correction","instruction":"Xatoni toping va to''g''rilang:","question":"I remember the summer where we visited Bukhara.","errorPart":"where","correct":"I remember the summer when we visited Bukhara.","explanation":"''Summer'' = time → ''when'', not ''where''."},{"id":77018,"type":"fill-blank","instruction":"Where yoki when bilan to''ldiring:","question":"Is this the restaurant ___ you had dinner?","blanks":["where"],"explanation":"''Restaurant'' = place → ''where''."}]},{"id":"common-mistakes","title":"O''zbeklar uchun keng tarqalgan xatolar","rule":"1),
('advanced-relative-clauses-b2', 'Advanced Relative Clauses (B2)', 'Reduced clauses, preposition+relative, compounds — murakkab nisbiy gaplar', 'B2', 1, 'Complex Structures', '{"formulas":[{"color":"green","label":"Reduced Relative (Active)","structure":"Noun + V+ing (replaces who/which + be + V+ing)\n  The man sitting there = The man who is sitting there","explanation":"Active reduced relative — ''who/which + be'' ni olib tashlab, V+ing qoldiriladi. Faqat defining relative clauses da mumkin.","whenToUse":"Gapni qisqartirish va zamonaviy uslubda yozish uchun. Faqat ''be'' fe''li bo''lgan relative clauselarda.","example":"The students waiting outside are cold. (Kutayotgan talabalar sovuq qotib turibdi)"},{"color":"orange","label":"Reduced Relative (Passive)","structure":"Noun + V³ (replaces who/which + be + V³)\n  The book published in 2020 was a bestseller.","explanation":"Passive reduced relative — ''who/which + be'' ni olib tashlab, V³ (past participle) qoldiriladi.","whenToUse":"Passiv relative clauselarni qisqartirish uchun. ''Which was written'' → ''written''.","example":"The research conducted last year is groundbreaking. (O''tgan yili o''tkazilgan tadqiqot)"},{"color":"blue","label":"Preposition + Relative Pronoun","structure":"Preposition + whom (people) / which (things)\n  The person to whom I spoke was helpful.","explanation":"Rasmiy (formal) ingliz tilida prepozitsiya relative pronoundan oldin keladi. Norasmiyda prepozitsiya gap oxirida qoladi.","whenToUse":"Rasmiy yozma ishlarda, akademik matnlarda, IELTS/CEFR yuqori ball uchun.","example":"The company for which I work is global. (Men ishlaydigan kompaniya global)"},{"color":"purple","label":"Compound Relative Pronouns","structure":"whoever / whatever / whichever / whenever / wherever\n  Whoever arrives first can start.","explanation":"Qo''shma nisbiy olmoshlar: whoever = anyone who, whatever = anything that, whichever = any that, whenever = any time when, wherever = any place where.","whenToUse":"Noaniq yoki umumiy shaxs/narsa/vaqt/joy haqida gapirganda.","example":"You can choose whatever you like. (Xohlagan narsangizni tanlashingiz mumkin)"},{"color":"red","label":"Quantifier + Relative Pronoun","structure":"many / some / all / most / none + of + whom / which\n  The students, many of whom passed, were relieved.","explanation":"Miqdor so''zlaridan keyin ''of whom'' (odamlar) yoki ''of which'' (narsalar) ishlatiladi. Bu B2 darajasidagi murakkab tuzilma.","whenToUse":"Bir guruhning qanchasi haqida ma''lumot berishda. Non-defining relative clause bilan ishlatiladi.","example":"The books, most of which were old, were donated. (Ko''pchiligi eski bo''lgan kitoblar)"}],"rules":["1️⃣ REDUCED RELATIVE CLAUSES (ACTIVE)\n\nDefining relative clauseni qisqartirish: ''who/which + be'' ni olib tashlab, V+ing qoldiriladi.\n\n📌 To''liq: The man who is sitting there is my brother.\n📌 Qisqa: The man sitting there is my brother.\n\n📌 Faqat ''be'' fe''li bo''lganda ishlaydi: ''who is'', ''which are'', ''who was''\n📌 Active → V+ing ishlatiladi: ''the woman wearing a hat''\n\n❌ The man sits there is my brother. (V+ing emas → XATO)\n✅ The man sitting there is my brother.","2️⃣ REDUCED RELATIVE CLAUSES (PASSIVE)\n\nPassive relative clauseni qisqartirish: ''which was / who were'' ni tashlab, V³ (past participle) qoldiriladi.\n\n📌 To''liq: The book which was written by her became famous.\n📌 Qisqa: The book written by her became famous.\n\n📌 Passive → V³ (past participle) ishlatiladi\n\n🔴 Active va Passive reduced farqiga e''tibor bering!\n  → The man driving the car (active: u haydayapti)\n  → The car driven by him (passive: u boshqaradi)\n\n❌ The book writing by her... (active → XATO, passive kerak)\n✅ The book written by her...","3️⃣ PREPOSITION + RELATIVE PRONOUN (FORMAL)\n\nRasmiy uslubda prepozitsiya relative pronoundan oldin keladi:\n\n📌 The person to whom I spoke → Men gaplashgan odam\n📌 The company for which I work → Men ishlaydigan kompaniya\n📌 The reason for which she left → Uning ketish sababi\n\n📌 Norasmiy uslubda prepozitsiya gap oxirida:\n  → The person who I spoke to...\n  → The company which I work for...\n\n🔴 Qoida: odam → whom, narsa → which\n🔴 ''Whom'' rasmiy, ''who'' norasmiy\n\n❌ The person to who I spoke... (to who → XATO, to whom kerak)\n✅ The person to whom I spoke...","4️⃣ COMPOUND RELATIVE PRONOUNS\n\nQo''shma nisbiy olmoshlar — ''ever'' qo''shimchasi orqali umumiy ma''no beradi:\n\n📌 Whoever = anyone who: Whoever wins gets a prize.\n📌 Whatever = anything that: Eat whatever you want.\n📌 Whichever = any one that: Choose whichever you like.\n📌 Whenever = any time when: Come whenever you can.\n📌 Wherever = any place where: Sit wherever you like.\n\n📌 Bu so''zlar gapda subject yoki object bo''lishi mumkin.\n📌 IELTS TIP: Compound relative pronouns — Band 7+ uchun muhim grammatik vosita.","5️⃣ WHICH REFERRING TO A WHOLE CLAUSE\n\n''Which'' butun bir oldingi gapga ishora qilishi mumkin (non-defining).\n\n📌 He passed the exam, which surprised everyone.\n📌 She was late, which made the boss angry.\n📌 They got married, which delighted their families.\n\n🔴 Bu non-defining relative clause — vergul bilan ajratiladi.\n🔴 ''That'' bu yerda ishlatilmaydi!\n\n📌 ''Which'' butun gapga ishora qiladi, birgina otga EMAS.","6️⃣ QUANTIFIER + RELATIVE PRONOUN\n\nSome/many/all/most/several/none + of + whom/which\n\n📌 The students, most of whom passed, celebrated.\n📌 The projects, several of which failed, were reviewed.\n📌 The teachers, all of whom are qualified, work hard.\n\n🔴 Bu non-defining relative clause — vergul bilan ajratiladi.\n🔴 Odamlar → of whom, narsalar → of which.\n\n📌 IELTS TIP: Quantifier + relative pronoun — akademik yozuvda juda foydali, Band 7+ uchun muhim.","7️⃣ O''ZBEKCHA XATOLAR\n\n📌 Reduced relative da V+ing va V³ farqini aralashtirish:\n  ❌ The book writing by him... (write = active, book = passive)\n  ✅ The book written by him...\n\n📌 Preposition + whom o''rniga ''to who'' ishlatish:\n  ❌ The person to who I spoke...\n  ✅ The person to whom I spoke...\n\n📌 ''Which'' butun gapga ishora qilganda ''that'' ishlatish:\n  ❌ He passed, that surprised everyone.\n  ✅ He passed, which surprised everyone.\n\n📌 Reduced relative ni noto''g''ri qo''llash:\n  ❌ The man sits there is my brother. (full verb not V+ing)\n  ✅ The man sitting there is my brother."],"vocabulary":[{"en":"reduced relative clause","uz":"qisqartirilgan nisbiy gap","example":"The man sitting there is my uncle.","rule":"V+ing / V³ replaces full clause"},{"en":"compound relative pronoun","uz":"qo''shma nisbiy olmosh","example":"Whoever arrives first can start.","rule":"whoever/whatever/whichever"},{"en":"preposition + relative","uz":"predlog + nisbiy olmosh","example":"The person to whom I spoke.","rule":"formal: to whom, for which"},{"en":"quantifier + relative","uz":"miqdor + nisbiy olmosh","example":"The students, many of whom passed.","rule":"some/most/all of whom/which"},{"en":"sentential relative","uz":"gapga ishora qiluvchi nisbiy","example":"He was late, which surprised me.","rule":"which → whole clause"},{"en":"whoever","uz":"kimki bo''lsa","example":"Whoever wants to join can come.","rule":"compound = anyone who"},{"en":"whatever","uz":"nima bo''lsa ham","example":"Eat whatever you like.","rule":"compound = anything that"},{"en":"whichever","uz":"qaysi biri bo''lsa","example":"Choose whichever you prefer.","rule":"compound = any that"},{"en":"whenever","uz":"qachon bo''lsa ham","example":"Visit whenever you have time.","rule":"compound = any time when"},{"en":"wherever","uz":"qayerda bo''lsa ham","example":"Sit wherever you find a seat.","rule":"compound = any place where"},{"en":"formal register","uz":"rasmiy uslub","example":"The company for which I work.","rule":"preposition + whom/which"},{"en":"informal register","uz":"norasmiy uslub","example":"The company which I work for.","rule":"preposition at end"},{"en":"past participle","uz":"o''tgan zamon sifatdoshi","example":"The book written by her.","rule":"V³ for passive reduced"},{"en":"present participle","uz":"hozirgi zamon sifatdoshi","example":"The girl singing on stage.","rule":"V+ing for active reduced"},{"en":"omission","uz":"tushirib qoldirish","example":"Reduced = omission of who/which + be.","rule":"drop pronoun + be"}],"examples":[{"en":"The man sitting next to me is a famous writer.","uz":"Yonimda o''tirgan odam mashhur yozuvchi."},{"en":"The research conducted last year was groundbreaking.","uz":"O''tgan yili o''tkazilgan tadqiqot kashfiyot edi."},{"en":"The person to whom I spoke was very helpful.","uz":"Men gaplashgan odam juda yordamchi edi."},{"en":"Whoever arrives first can start the meeting.","uz":"Kim birinchi bo''lib kelsa, majlisni boshlashi mumkin."},{"en":"He was late, which annoyed the manager.","uz":"U kechikdi, bu menejerning jahlini chiqardi."},{"en":"The students, most of whom passed, were relieved.","uz":"Talabalar, ko''pchiligi o''tgan, yengil nafas oldi."},{"en":"Choose whichever option you prefer.","uz":"Qaysi variantni xohlasangiz, shuni tanlang."},{"en":"The company for which she works is global.","uz":"U ishlaydigan kompaniya global."}],"specialCases":[{"id":"active-vs-passive-reduced","title":"Active va Passive Reduced farqi","rule":"ACTIVE: noun + V+ing (the man sitting = who is sitting). PASSIVE: noun + V³ (the book written = which was written). Agar fe''l active bo''lsa → V+ing, agar passive bo''lsa → V³.","mnemonic":"Active = -ing (doing), Passive = -ed/-en (done). The man DRIVING (active: u haydayapti). The car DRIVEN (passive: uni haydaydilar).","commonMistakes":"The book writing by the author (writing → written). The man driven the car (driven → driving).","examples":[{"en":"The girl singing on stage is my cousin. (active)","uz":"Sahnada kuylayotgan qiz mening amakivachcham."},{"en":"The song sung by her was beautiful. (passive)","uz":"U tomonidan aytilgan qo''shiq go''zal edi."}],"drills":[{"id":880010,"type":"fill-blank","instruction":"Reduced relative (active V+ing):","question":"The man ___ (sit) next to me is a doctor.","blanks":["sitting"],"explanation":"Active → V+ing: ''who is sitting'' → ''sitting''."},{"id":880011,"type":"fill-blank","instruction":"Reduced relative (passive V³):","question":"The book ___ (write) by her became a bestseller.","blanks":["written"],"explanation":"Passive → V³: ''which was written'' → ''written''."},{"id":880012,"type":"error-correction","instruction":"Xatoni toping:","question":"The man driven the car is my father.","errorPart":"driven","correct":"The man driving the car is my father.","explanation":"Active → ''driving'' (V+ing), not ''driven'' (V³ passive)."},{"id":880013,"type":"error-correction","instruction":"Xatoni toping:","question":"The cake making by my mother was delicious.","errorPart":"making","correct":"The cake made by my mother was delicious.","explanation":"Passive → ''made'' (V³), not ''making'' (V+ing active)."}]},{"id":"preposition-relative-formal","title":"Preposition + Relative — Rasmiy uslub","rule":"Rasmiy: preposition + whom (people) / which (things). Norasmiy: preposition oxirida. ''To whom'' = kimga, ''for which'' = qaysi uchun, ''in which'' = qaysida, ''about whom'' = kim haqida.","mnemonic":"Rasmiy = preposition BEFORE. Norasmiy = preposition AFTER. ''The person TO WHOM'' = formal. ''The person WHO... TO'' = informal.","commonMistakes":"''To who'' xato → ''to whom'' kerak. ''With which'' narsa uchun, ''with whom'' odam uchun.","examples":[{"en":"The person about whom we were talking is here. (formal)","uz":"Biz gapirgan odam shu yerda."},{"en":"The person who we were talking about is here. (informal)","uz":"Biz gapirgan odam shu yerda."}],"drills":[{"id":880020,"type":"fill-blank","instruction":"Preposition + whom bilan:","question":"The person ___ whom I spoke was kind.","blanks":["to"],"explanation":"''To whom'' = kimga. Formal: to + whom."},{"id":880021,"type":"fill-blank","instruction":"Preposition + which bilan:","question":"The company ___ which I work is large.","blanks":["for"],"explanation":"''For which'' = qaysi kompaniyada. Formal: for + which."},{"id":880022,"type":"error-correction","instruction":"Xatoni toping:","question":"The person to who I spoke was the manager.","errorPart":"to who","correct":"The person to whom I spoke was the manager.","explanation":"Prepositiondan keyin ''whom'', ''who'' emas."},{"id":880023,"type":"transformation","instruction":"Rasmiy shaklga o''tkazing:","question":"The person who I work with is helpful.","hint":"The person with whom...","correct":"The person with whom I work is helpful.","explanation":"Informal ''who...with'' → formal ''with whom''."}]},{"id":"compound-relatives","title":"Compound Relative Pronouns","rule":"Whoever = anyone who. Whatever = anything that. Whichever = any one that. Whenever = any time when. Wherever = any place where.","mnemonic":"Whoever = Who + ever (anyone who). Whatever = What + ever (anything that). Ever = ''any'' ma''nosini qo''shadi.","commonMistakes":"''Whatever'' ni ''no matter what'' ma''nosida ishlatish mumkin. ''What ever'' (two words) = ''what'' so''roq so''zi + ''ever'' urg''u (= what on earth).","examples":[{"en":"Whoever finishes first wins a prize.","uz":"Kim birinchi bo''lib tugatsa, sovrin oladi."},{"en":"You can invite whomever you like. (formal)","uz":"Kimni xohlasangiz, taklif qilishingiz mumkin."}],"drills":[{"id":880030,"type":"fill-blank","instruction":"Compound relative:","question":"___ finishes first will get a prize.","blanks":["Whoever"],"explanation":"''Whoever'' = anyone who."},{"id":880031,"type":"fill-blank","instruction":"Compound relative:","question":"You can eat ___ you want.","blanks":["whatever"],"explanation":"''Whatever'' = anything that."},{"id":880032,"type":"fill-blank","instruction":"Compound relative:","question":"Choose ___ colour you prefer.","blanks":["whichever"],"explanation":"''Whichever'' = any one that."},{"id":880033,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"___ wants to join is welcome.","options":["Whoever","Whatever","Whichever","Whenever"],"correct":"Whoever","explanation":"''Whoever'' = anyone who + verb."}]}],"exercises":[{"id":880040,"type":"fill-blank","instruction":"Reduced relative — active V+ing:","question":"The woman ___ (stand) at the door is my teacher.","blanks":["standing"],"explanation":"''Who is standing'' → ''standing''. Active reduced."},{"id":880041,"type":"fill-blank","instruction":"Reduced relative — passive V³:","question":"The article ___ (publish) last month was controversial.","blanks":["published"],"explanation":"''Which was published'' → ''published''. Passive reduced."},{"id":880042,"type":"fill-blank","instruction":"Preposition + whom:","question":"The colleagues ___ whom I work are very supportive.","blanks":["with"],"explanation":"''With whom'' = kim bilan. Formal preposition structure."},{"id":880043,"type":"fill-blank","instruction":"Preposition + which:","question":"The project ___ which I''m responsible is almost done.","blanks":["for"],"explanation":"''For which'' = nima uchun mas''ul."},{"id":880044,"type":"fill-blank","instruction":"Compound relative:","question":"___ you decide, I''ll support you.","blanks":["Whatever"],"explanation":"''Whatever'' = no matter what."},{"id":880045,"type":"fill-blank","instruction":"Quantifier + relative:","question":"The applicants, several ___ whom were overqualified, were rejected.","blanks":["of"],"explanation":"''Several of whom'' = ulardan bir nechtasi."},{"id":880046,"type":"fill-blank","instruction":"Sentential which:","question":"She passed the exam, ___ delighted her parents.","blanks":["which"],"explanation":"''Which'' refers to the whole clause ''she passed the exam''."},{"id":880047,"type":"fill-blank","instruction":"Reduced relative — active:","question":"The children ___ (play) in the garden are my neighbours.","blanks":["playing"],"explanation":"''Who are playing'' → ''playing''. Active reduced."},{"id":880048,"type":"fill-blank","instruction":"Reduced relative — passive:","question":"The documents ___ (sign) yesterday are important.","blanks":["signed"],"explanation":"''Which were signed'' → ''signed''. Passive reduced."},{"id":880049,"type":"fill-blank","instruction":"Compound relative — place:","question":"Sit ___ you like.","blanks":["wherever"],"explanation":"''Wherever'' = any place where."},{"id":880050,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"The man ___ next to me is a professor.","options":["sitting","sat","was sitting","who sitting"],"correct":"sitting","explanation":"Reduced: ''who is sitting'' → ''sitting''."},{"id":880051,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"The research ___ in 2023 was groundbreaking.","options":["conducting","conducted","was conducted","which conducting"],"correct":"conducted","explanation":"Reduced passive: ''which was conducted'' → ''conducted''."},{"id":880052,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"The person ___ I spoke yesterday is the CEO.","options":["to whom","to who","whom to","which to"],"correct":"to whom","explanation":"Formal: preposition + whom. ''To whom''."},{"id":880053,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"___ comes first can start the game.","options":["Whoever","Whatever","Whichever","However"],"correct":"Whoever","explanation":"''Whoever'' = anyone who. Odamlar uchun."},{"id":880054,"type":"multiple-choice","instruction":"To''g''ri variantni tanlang:","question":"He forgot the meeting, ___ was unusual.","options":["which","that","what","who"],"correct":"which","explanation":"''Which'' butun gapga ishora qiladi. ''That'' bu yerda ishlatilmaydi."},{"id":880055,"type":"error-correction","instruction":"Xatoni toping:","question":"The girl wearing dress is my sister. The cake making by her is delicious.","errorPart":"making","correct":"The girl wearing a dress is my sister. The cake made by her is delicious.","explanation":"First: active ✅. Second: passive → ''made'' (V³), not ''making''."},{"id":880056,"type":"error-correction","instruction":"Xatoni toping:","question":"The person to who I spoke was the director.","errorPart":"to who","correct":"The person to whom I spoke was the director.","explanation":"Preposition + whom (not who). Formal structure."},{"id":880057,"type":"error-correction","instruction":"Xatoni toping:","question":"He was late, that surprised everyone.","errorPart":"that","correct":"He was late, which surprised everyone.","explanation":"Sentential relative → ''which'', not ''that''."},{"id":880058,"type":"error-correction","instruction":"Xatoni toping:","question":"The book writing by the author is famous.","errorPart":"writing","correct":"The book written by the author is famous.","explanation":"Passive reduced → V³ ''written'', not V+ing ''writing''."},{"id":880059,"type":"transformation","instruction":"Reduced relative ga o''tkazing:","question":"The woman who is standing there is my aunt.","hint":"The woman standing...","correct":"The woman standing there is my aunt.","explanation":"''Who is standing'' → ''standing''. Active reduced."},{"id":880060,"type":"transformation","instruction":"Reduced relative ga o''tkazing:","question":"The house which was built in 1990 is for sale.","hint":"The house built...","correct":"The house built in 1990 is for sale.","explanation":"''Which was built'' → ''built''. Passive reduced."},{"id":880061,"type":"transformation","instruction":"Formal shaklga o''tkazing:","question":"The person who I work for is very kind.","hint":"The person for whom...","correct":"The person for whom I work is very kind.","explanation":"Informal → formal: ''who...for'' → ''for whom''."},{"id":880062,"type":"transformation","instruction":"Compound relative bilan yozing:","question":"Any person who finishes first gets a prize.","hint":"Whoever finishes...","correct":"Whoever finishes first gets a prize.","explanation":"''Any person who'' → ''whoever''. Compound relative."},{"id":880063,"type":"transformation","instruction":"Quantifier + relative bilan yozing:","question":"The students passed. Most of them studied hard.","hint":"The students, most of whom...","correct":"The students, most of whom studied hard, passed.","explanation":"''Most of them'' → ''most of whom''. Non-defining clause."},{"id":880064,"type":"fill-blank","instruction":"Aralash — reduced/preposition/compound:","question":"The man ___ at the desk is my boss. The person ___ whom I spoke was his assistant. ___ wants to join, let me know.","blanks":["sitting","to","Whoever"],"explanation":"Reduced (sitting), preposition+whom (to whom), compound (whoever)."},{"id":880065,"type":"fill-blank","instruction":"Aralash — reduced/preposition/which:","question":"The research ___ in 2022 was published. The company ___ which we work is IBM. He won, ___ was expected.","blanks":["conducted","for","which"],"explanation":"Passive reduced (conducted), preposition+which (for which), sentential which."}],"exerciseSections":[{"ids":[880040,880041,880042,880043,880044,880045,880046,880047,880048,880049],"desc":"Reduced, Preposition, Compound","icon":"🌱","color":"bg-emerald-500","title":"Boshlang''ich"},{"ids":[880050,880051,880052,880053,880054],"desc":"MCQ tanlash","icon":"📘","color":"bg-blue-500","title":"O''rtacha"},{"ids":[880055,880056,880057,880058],"desc":"Xato tuzatish","icon":"🎯","color":"bg-violet-500","title":"Qiyin"},{"ids":[880059,880060,880061,880062,880063],"desc":"Transformatsiya","icon":"🔄","color":"bg-rose-500","title":"Murakkab"},{"title":"🔀 Aralash","desc":"Reduced + Preposition + Which + Compounds","color":"bg-fuchsia-500","icon":"🔄","ids":[880064,880065]}],"tests":[{"id":880070,"type":"multiple-choice","instruction":"Asosiy:","question":"Active reduced relative qanday yasaladi?","options":["Noun + V³","Noun + V+ing","Noun + to V¹","Noun + being + V³"],"correct":"Noun + V+ing","explanation":"Active: noun + V+ing (the man sitting)."},{"id":880071,"type":"multiple-choice","instruction":"Asosiy:","question":"Passive reduced relative qanday yasaladi?","options":["Noun + V+ing","Noun + V³","Noun + being","Noun + having + V³"],"correct":"Noun + V³","explanation":"Passive: noun + V³ (the book written)."},{"id":880072,"type":"multiple-choice","instruction":"Asosiy:","question":"Rasmiy uslubda preposition qayerda turadi?","options":["Gap oxirida","Relative pronoun dan oldin","Relative pronoun dan keyin","Hech qayerda"],"correct":"Relative pronoun dan oldin","explanation":"Formal: preposition + whom/which (to whom, for which)."},{"id":880073,"type":"multiple-choice","instruction":"Asosiy:","question":"''Whoever'' nimani anglatadi?","options":["Kim bo''lsa","Nima bo''lsa","Qaysi biri","Qachon bo''lsa"],"correct":"Kim bo''lsa","explanation":"''Whoever'' = anyone who = kim bo''lsa."},{"id":880074,"type":"multiple-choice","instruction":"Asosiy:","question":"Sentential ''which'' nimaga ishora qiladi?","options":["Bir otga","Butun gapga","Bir fe''lga","Bir sifatga"],"correct":"Butun gapga","explanation":"''Which'' butun oldingi gapga ishora qiladi."},{"id":880075,"type":"multiple-choice","instruction":"O''rtacha:","question":"The research ___ in 2023 showed interesting results.","options":["conducting","conducted","was conducted","which conducting"],"correct":"conducted","explanation":"Passive reduced: ''which was conducted'' → ''conducted''."},{"id":880076,"type":"multiple-choice","instruction":"O''rtacha:","question":"The person ___ I had dinner is my colleague.","options":["with whom","with who","which with","whom with"],"correct":"with whom","explanation":"Formal: ''with whom''. Preposition + whom."},{"id":880077,"type":"multiple-choice","instruction":"O''rtacha:","question":"___ wants to participate must register.","options":["Whoever","Whatever","Whichever","However"],"correct":"Whoever","explanation":"''Whoever'' = anyone who + verb (wants)."},{"id":880078,"type":"multiple-choice","instruction":"O''rtacha:","question":"The students, most ___ whom passed, were happy.","options":["of","in","to","with"],"correct":"of","explanation":"''Most of whom'' — quantifier + of + whom."},{"id":880079,"type":"multiple-choice","instruction":"O''rtacha:","question":"He was late, ___ was unusual for him.","options":["which","that","what","this"],"correct":"which","explanation":"Sentential relative → ''which''."},{"id":880080,"type":"multiple-choice","instruction":"Qiyin:","question":"Qaysi gapda reduced relative TO''G''RI ishlatilgan?","options":["The man driving the car is my friend","The man driven the car is my friend","The man was driving the car is my friend","The man who driving the car is my friend"],"correct":"The man driving the car is my friend","explanation":"''Driving'' = active reduced V+ing. To''g''ri variant."},{"id":880081,"type":"multiple-choice","instruction":"Qiyin:","question":"Qaysi gapda preposition + relative TO''G''RI?","options":["The person to who I spoke","The person whom to I spoke","The person to whom I spoke","The person who to I spoke"],"correct":"The person to whom I spoke","explanation":"Preposition + whom: ''to whom''."},{"id":880082,"type":"multiple-choice","instruction":"Qiyin:","question":"''The cake making by her'' nima uchun xato?","options":["''Making'' active, passive kerak","''Cake'' noto''g''ri","''Her'' noto''g''ri","Xato emas"],"correct":"''Making'' active, passive kerak","explanation":"Passive → ''made'' (V³). ''Making'' = active V+ing."},{"id":880083,"type":"multiple-choice","instruction":"Murakkab:","question":"Qaysi gap BARCHA elementlarni o''z ichiga oladi?","options":["The research conducted last year, which was groundbreaking, surprised everyone.","The man sitting there is my uncle.","Whoever comes is welcome.","I like the book."],"correct":"The research conducted last year, which was groundbreaking, surprised everyone.","explanation":"Passive reduced (conducted) + non-defining which. B2 level."}],"testSections":[{"ids":[880070,880071,880072,880073,880074],"desc":"Asosiy tushunchalar","icon":"🌱","color":"bg-emerald-500","title":"Oson"},{"ids":[880075,880076,880077,880078,880079],"desc":"Qo''llash","icon":"📘","color":"bg-blue-500","title":"O''rtacha"},{"ids":[880080,880081,880082],"desc":"Tahlil","icon":"🎯","color":"bg-violet-500","title":"Qiyin"},{"ids":[880083],"desc":"Murakkab tahlil","icon":"🏆","color":"bg-rose-500","title":"Murakkab"}],"reading":{"passage":"An Innovative Company\n\nInnovateCorp, founded in 2018, has become a leader in the tech industry. The company, for which many top engineers work, specializes in artificial intelligence. The CEO, respected by everyone in the field, started the company in her garage.\n\nThe team working on the new AI project has made remarkable progress. The research conducted last year led to a breakthrough. The product, several features of which were revolutionary, won several awards.\n\nWhoever joins InnovateCorp can expect a challenging but rewarding experience. The company, the culture of which is collaborative, encourages innovation. Employees, many of whom come from top universities, contribute to cutting-edge projects.\n\nThe company expanded rapidly in 2023, which surprised many analysts. The strategies implemented by the leadership team proved highly effective. Whatever challenges arise, the team always finds creative solutions. This is a workplace where innovation thrives, which is exactly what makes it special.","questions":[{"id":880090,"type":"multiple-choice","question":"What is ''founded in 2018'' an example of?","options":["Active reduced relative","Passive reduced relative","Preposition + relative","Compound relative"],"correctIndex":1,"explanation":"''Founded'' = ''which was founded''. Passive reduced relative clause."},{"id":880091,"type":"multiple-choice","question":"What relative structure is in ''the company for which many top engineers work''?","options":["Reduced relative","Preposition + relative","Compound relative","Quantifier + relative"],"correctIndex":1,"explanation":"''For which'' = preposition + relative pronoun (formal)."},{"id":880092,"type":"multiple-choice","question":"What does ''whoever'' introduce in the passage?","options":["A specific person","Any person who joins","No one","The CEO"],"correctIndex":1,"explanation":"''Whoever joins InnovateCorp'' = ''anyone who joins''."},{"id":880093,"type":"multiple-choice","question":"What is ''many of whom'' an example of?","options":["Reduced relative","Preposition + relative","Quantifier + relative pronoun","Sentential which"],"correctIndex":2,"explanation":"''Many of whom'' = quantifier (many) + of + relative pronoun (whom)."},{"id":880094,"type":"multiple-choice","question":"What does ''which'' refer to in ''...expanded rapidly, which surprised many analysts''?","options":["The company","The rapid expansion","The leadership team","The products"],"correctIndex":1,"explanation":"''Which'' refers to the whole clause ''the company expanded rapidly''."}]},"writing":{"prompt":"Write a formal paragraph (100-120 words) about a person who has influenced your life. Use at least two reduced relative clauses (e.g., ''The person inspiring me...''), one preposition + relative pronoun structure (e.g., ''the person to whom I look up''), and one sentence with ''which'' referring to a whole clause.","wordLimit":120,"tips":["Use reduced relatives: ''The person inspiring me most is...''","Use passive reduced: ''The lessons learned from her are...''","Use preposition + whom/which for formal tone","End with a ''which'' clause referring to your whole sentence"]},"listening":{"transcript":"Professor: Today we''ll discuss advanced relative clauses. First, reduced relatives. The man sitting at the desk is our director. That''s shorter than saying ''the man who is sitting at the desk''.\\nStudent: So we drop the pronoun and ''be'' verb?\\nProfessor: Exactly. For passive: ''The research conducted last year showed great results'' instead of ''which was conducted''.\\nStudent: What about formal writing? I''ve seen ''the person to whom I spoke''.\\nProfessor: Yes! Preposition + whom/which is formal. In speech we say ''the person who I spoke to''.\\nStudent: And ''whoever'' vs ''who''?\\nProfessor: ''Whoever'' means ''anyone who''. ''Whoever arrives first can start.''\\nStudent: What about ''many of whom''?\\nProfessor: That''s a quantifier + relative pronoun. ''The students, many of whom passed, were happy.''\\nStudent: One more — can ''which'' refer to a whole sentence?\\nProfessor: Yes! ''He was late, which surprised everyone.''","vocabulary":[{"word":"reduced relative","definition":"qisqartirilgan nisbiy gap"},{"word":"compound relative","definition":"qo''shma nisbiy olmosh (whoever, whatever)"},{"word":"quantifier","definition":"miqdor so''zi (many, some, all)"},{"word":"formal register","definition":"rasmiy uslub"},{"word":"refer to","definition":"ishora qilmoq"}],"questions":[{"id":880001,"type":"multiple-choice","question":"What is ''The man sitting at the desk'' an example of?","options":["Full relative clause","Reduced relative clause","Compound relative","Preposition + relative"],"correctIndex":1,"explanation":"''Sitting'' = reduced form of ''who is sitting''."},{"id":880002,"type":"multiple-choice","question":"How do we form passive reduced relatives?","options":["Use V+ing","Use V³ (past participle)","Use ''being''","Use ''having''"],"correctIndex":1,"explanation":"Passive: ''conducted'' = ''which was conducted'' (V³)."},{"id":880003,"type":"true-false","question":"''The person to whom I spoke'' is informal.","answer":false,"explanation":"Preposition + whom is FORMAL. Informal: ''the person who I spoke to''."},{"id":880004,"type":"multiple-choice","question":"What does ''whoever'' mean?","options":["Only one person","Anyone who","No one","Someone specific"],"correctIndex":1,"explanation":"''Whoever'' = ''anyone who'' — a compound relative pronoun."},{"id":880005,"type":"multiple-choice","question":"In ''He was late, which surprised everyone'', what does ''which'' refer to?","options":["The person","The whole clause ''He was late''","The time","Everyone"],"correctIndex":1,"explanation":"''Which'' can refer to the entire preceding clause."}],"difficulty":"hard","topic":"Murakkab nisbiy gaplar — reduced, preposition+relative, compounds"},"dialogues":[{"id":"advanced-relative-practice","title":"Advanced Relative Clauses amaliyot","context":"Ikki kollega murakkab nisbiy gaplarni ishlatib loyiha haqida gaplashishmoqda.","lines":[{"speaker":"Alisher","text":"Have you met the person leading the new project?","translation":"Yangi loyihani boshqarayotgan odam bilan tanishdingizmi?"},{"speaker":"Madina","text":"Yes! The person to whom I spoke yesterday was very knowledgeable.","translation":"Ha! Kecha men gaplashgan odam juda bilimdon edi."},{"speaker":"Alisher","text":"The research conducted by his team is impressive.","translation":"Uning jamoasi tomonidan o''tkazilgan tadqiqot ta''sirli."},{"speaker":"Madina","text":"They hired several new engineers, most of whom have PhDs.","translation":"Ular bir nechta yangi muhandislarni yollashdi, ko''pchiligi PhD darajasiga ega."},{"speaker":"Alisher","text":"Whoever works on this project will learn a lot.","translation":"Bu loyihada kim ishlasa, ko''p narsa o''rganadi."},{"speaker":"Madina","text":"They secured funding, which was crucial for the project.","translation":"Ular moliyalashtirishni ta''minlashdi, bu loyiha uchun juda muhim edi."}]}],"culturalNotes":[{"id":"academic-formal-style","title":"Akademik va rasmiy uslubda relative clauses","description":"Akademik yozuvda preposition + whom/which tuzilmalari keng qo''llaniladi. Bu uslub IELTS/CEFR B2 va yuqori darajalarida talab qilinadi. Norasmiy suhbatda ''the person who I spoke to'' ishlatilsa, rasmiy esseda ''the person to whom I spoke'' yoziladi. O''zbek talabalari ko''pincha rasmiy uslubni o''rganishda qiynalishadi, chunki o''zbek tilida bu farq yo''q.","icon":"📝","category":"academic"},{"id":"compounds-in-english","title":"Ingliz tilidagi ''ever'' qo''shimchasi","description":"Ingliz tilida ''-ever'' qo''shimchasi ''any'' ma''nosini beradi: whoever = anyone who, whatever = anything that, wherever = any place where. Bu so''zlar o''zbek tilida ''kim bo''lsa'', ''nima bo''lsa'' kabi tarjima qilinadi va juda keng qo''llaniladi. Norwegian, Swedish kabi tillarda ham shunday tuzilmalar bor.","icon":"🌍","category":"language"}]}'::jsonb)

ON CONFLICT (id) DO UPDATE SET
  title    = EXCLUDED.title,
